
// Performance optimization utilities
function throttle(func, limit) {
  var inThrottle = false;
  return function() {
    var args = arguments;
    var context = this;
    if (!inThrottle) {
      func.apply(context, args);
      inThrottle = true;
      setTimeout(function(){inThrottle = false}, limit);
    }
  }
}

function debounce(func, wait) {
  var timeout;
  return function() {
    var args = arguments;
    var context = this;
    clearTimeout(timeout);
    timeout = setTimeout(function(){func.apply(context, args)}, wait);
  }
}

function rafThrottle(func) {
  var running = false;
  return function() {
    if (!running) {
      running = true;
      var args = arguments;
      var ctx = this;
      requestAnimationFrame(function() {
        func.apply(ctx, args);
        running = false;
      });
    }
  }
}

var activeTimers = [];
function safeSetTimeout(fn, delay) {
  var timer = setTimeout(function() {
    var idx = activeTimers.indexOf(timer);
    if (idx >= 0) activeTimers.splice(idx, 1);
    fn();
  }, delay);
  activeTimers.push(timer);
  return timer;
}

function safeSetInterval(fn, delay) {
  var interval = setInterval(fn, delay);
  activeTimers.push(interval);
  return interval;
}

function clearAllTimers() {
  activeTimers.forEach(function(timer) {
    try { clearTimeout(timer); clearInterval(timer); } catch(e) {}
  });
  activeTimers = [];
}

function cancelSafeTimer(timer) {
  var idx = activeTimers.indexOf(timer);
  if (idx >= 0) {
    activeTimers.splice(idx, 1);
  }
  try { clearTimeout(timer); clearInterval(timer); } catch(e) {}
}

