// localforage 内联版（不再依赖 CDN 加载）
var _inlineLocalforageLoaded = false;
function _initLocalforage(){
  if(!window.localforage)return false;
  if(_inlineLocalforageLoaded)return true;
  _inlineLocalforageLoaded = true;
  try{
    localforage.config({driver:[localforage.INDEXEDDB,localforage.WEBSQL,localforage.LOCALSTORAGE],name:'Star',version:2.0,storeName:'star_data',description:'Dual-storage for Star v1.0.0 - IndexedDB primary + localStorage fallback'});
    // 请求持久化存储，防止浏览器自动清理
    if(navigator.storage&&navigator.storage.persist){
      navigator.storage.persist().then(function(persistent){
        console.log('Persistent storage granted:',persistent);
        if(!persistent&&navigator.storage.requestPersistent){
          navigator.storage.requestPersistent().then(function(granted){
            console.log('Persistent storage requested:',granted);
          }).catch(function(e){console.warn('Failed to request persistent storage:',e)});
        }
      }).catch(function(e){console.warn('Failed to check persistent storage:',e)});
    }
    // 估算存储配额
    if(navigator.storage&&navigator.storage.estimate){
      navigator.storage.estimate().then(function(est){
        console.log('Storage estimate: usage='+(est.usage/1024/1024).toFixed(2)+'MB, quota='+(est.quota/1024/1024).toFixed(2)+'MB, percent='+(est.usage/est.quota*100).toFixed(1)+'%');
      }).catch(function(){});
    }
    // 标记 Storage 模块中 localforage 已就绪
    if(typeof Storage !== 'undefined' && Storage.markReady) {
      Storage.markReady();
    }
    if(typeof migrateFromMoonlight === 'function'){
      migrateFromMoonlight().then(function(){
        if(typeof Storage !== 'undefined' && Storage.restoreFromDB) {
          Storage.restoreFromDB();
        }
        renderChatList();
      });
    }else{
      setTimeout(function(){
        if(typeof migrateFromMoonlight === 'function'){
          migrateFromMoonlight().then(function(){
            if(typeof Storage !== 'undefined' && Storage.restoreFromDB) {
              Storage.restoreFromDB();
            }
            renderChatList();
          });
        }else{
          if(typeof Storage !== 'undefined' && Storage.restoreFromDB) {
            Storage.restoreFromDB();
          }
          renderChatList();
        }
      },100);
    }
    window.dispatchEvent(new Event('localforageReady'));
  }catch(e){console.warn('localforage init error:',e);}
  return true;
}
// 兜底：若内联加载失败，回退到 CDN（正常情况下不会执行）
(function(){
  if(window.localforage){ if(_initLocalforage()) return; }
  var cdns=[
    'https://cdnjs.cloudflare.com/ajax/libs/localforage/1.10.0/localforage.min.js',
    'https://cdn.bootcdn.net/ajax/libs/localforage/1.10.0/localforage.min.js',
    'https://unpkg.com/localforage@1.10.0/dist/localforage.min.js',
    'https://cdn.jsdelivr.net/npm/localforage@1.10.0/dist/localforage.min.js'
  ];
  var idx=0;
  function tryLoad(){
    if(idx>=cdns.length){
      console.warn('localforage failed to load from all CDNs, using localStorage fallback');
      window.dispatchEvent(new Event('localforageFailed'));
      return;
    }
    var s=document.createElement('script');
    s.src=cdns[idx];
    var loadTimeout=setTimeout(function(){
      console.warn('localforage CDN timeout:',cdns[idx]);
      s.onload=null;s.onerror=null;
      if(s.parentNode)s.parentNode.removeChild(s);
      idx++;
      tryLoad();
    },3000);
    s.onload=function(){
      clearTimeout(loadTimeout);
      if(window.localforage){
        console.log('localforage loaded from:',cdns[idx]);
        if(_initLocalforage()) return;
      }
      idx++;
      tryLoad();
    };
    s.onerror=function(){clearTimeout(loadTimeout);idx++;tryLoad()};
    document.head.appendChild(s);
  }
  tryLoad();
})();


