// 全局未捕获 Promise 异常处理，防止静默白屏
window.addEventListener('unhandledrejection',function(e){
  console.error('Unhandled rejection:',e.reason);
  // 防抖：同一错误在 1 秒内只处理一次，避免高频报错导致页面被反复重渲染、按钮失效
  var now=Date.now();
  if(window._lastUnhandledTs&&(now-window._lastUnhandledTs)<1000){
    e.preventDefault&&e.preventDefault();
    return;
  }
  window._lastUnhandledTs=now;
  // 隐藏早期加载动画
  try{var el=document.getElementById('early-loading');if(el)el.style.display='none';}catch(e3){}
  // 确保 phone 容器可见
  var phone=document.querySelector('.phone');
  if(phone && phone.style.opacity==='0'){
    phone.style.display='flex';
    phone.style.opacity='1';
  }
  var ann=document.getElementById('announcement-screen');
  if(ann && ann.style.display!=='none'){
    ann.style.opacity='0';
    setTimeout(function(){ann.style.display='none';ann.style.pointerEvents='none';},500);
  }
  try{showPg('pg-list');renderChatList();}catch(e2){}
});

// DOM 加载完成后确保 phone 最终可见（兜底机制）
document.addEventListener('DOMContentLoaded',function(){
  setTimeout(function(){
    var phone=document.querySelector('.phone');
    var ann=document.getElementById('announcement-screen');
    // 如果 5 秒后 phone 仍然不可见，强制显示
    setTimeout(function(){
      if(phone && (phone.style.opacity==='0' || phone.style.display==='none')){
        console.warn('Force showing phone after 5s timeout');
        try{var el=document.getElementById('early-loading');if(el)el.style.display='none';}catch(e3){}
        phone.style.display='flex';
        phone.style.opacity='1';
        if(ann){ann.style.display='none';ann.style.pointerEvents='none';}
        try{showPg('pg-list');renderChatList();}catch(e2){}
      }
    },5000);
    // 2 秒后也检查一次（兜底更快）
    setTimeout(function(){
      var elEarly=document.getElementById('early-loading');
      if(elEarly&&elEarly.style.display!=='none')return;
      if(phone && (phone.style.opacity==='0' || phone.style.display==='none')){
        console.warn('Force showing phone after 2s quick check');
        phone.style.display='flex';
        phone.style.opacity='1';
        if(ann){ann.style.display='none';ann.style.pointerEvents='none';}
        try{showPg('pg-list');renderChatList();}catch(e2){}
      }
    },2000);
  },0);
});

// 全局错误处理：确保发生 JS 错误时 phone 仍然可见
window.addEventListener('error',function(e){
  var phone=document.querySelector('.phone');
  if(phone && (phone.style.opacity==='0' || phone.style.display==='none')){
    console.warn('Global error caught, forcing phone display');
    phone.style.display='flex';
    phone.style.opacity='1';
    var ann=document.getElementById('announcement-screen');
    if(ann){ann.style.display='none';ann.style.pointerEvents='none';}
    try{showPg('pg-list');renderChatList();}catch(e2){}
  }
});

var $=function(id){return document.getElementById(id)};
var bindEvt=function(id,evt,fn){var el=$(id);if(el)el.addEventListener(evt,fn);};
var safeAddEvent=function(id,evt,fn,opts){var el=$(id);if(el){if(opts)el.addEventListener(evt,fn,opts);else el.addEventListener(evt,fn);}return !!el;};
var chatBgCache={};
var SELF='user',OTHER='partner',LC='ml2_c',LP='ml2_p',LM='ml2_m_',LD='ml2_d_',LL='ml2_letters',LMOM='ml2_moments',LLIKE='ml2_like_';
// 全局防误触：在touchend时用changedTouches计算总移动距离（而非touchmove中间值），
// 避免高灵敏度触屏（如荣耀100）在点击时产生微小touchmove导致误判为滑动
// 使用捕获阶段确保touchend在按钮的touchend之前触发
var _tsX=0,_tsY=0,_tsM=false;
document.addEventListener('touchstart',function(e){_tsX=e.touches[0].clientX;_tsY=e.touches[0].clientY;_tsM=false},{passive:true,capture:true});
function isSwipe(){return _tsM;}
document.addEventListener('touchend',function(e){
  var dx=e.changedTouches[0].clientX-_tsX;
  var dy=e.changedTouches[0].clientY-_tsY;
  _tsM=(Math.abs(dx)>20||Math.abs(dy)>20);
  if(_tsM){
    e.stopPropagation();
  }
},{passive:false,capture:true});
document.addEventListener('click',function(e){
  if(isSwipe()){
    _tsM=false;
    var tag=e.target.tagName;
    var hasOnclickAttr=!!e.target.closest('[onclick]');
    var hasJSOnclick=false;
    var el=e.target;
    for(var d=0;d<4&&el;d++){if(el.onclick){hasJSOnclick=true;break;}el=el.parentElement;}
    var isInteractive=tag==='BUTTON'||tag==='A'||tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT'||e.target.closest('button')||e.target.closest('a')||e.target.closest('.mo-action')||e.target.closest('[data-action]')||hasOnclickAttr||hasJSOnclick;
    if(!isInteractive){
      e.stopPropagation();
      e.preventDefault();
    }
  }
},true);

function setupKeyboardFix(){
  var isMobile=/iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
  if(!isMobile)return;
  
  var phone=document.querySelector('.phone');
  var msgbox=document.getElementById('msgbox');
  var inputWrap=document.querySelector('.input-wrap');
  
  var originalHeight=window.innerHeight;
  var vvHeight=window.innerHeight;
  
  if(window.visualViewport){
    var _vvResizeTimer=null;
    window.visualViewport.addEventListener('resize',function(){
      var newHeight=window.visualViewport.height;
      var heightDiff=originalHeight-newHeight;
      
      if(heightDiff>50){
        if(_vvResizeTimer)clearTimeout(_vvResizeTimer);
        _vvResizeTimer=setTimeout(function(){
          if(msgbox)msgbox.scrollTop=msgbox.scrollHeight;
        },100);
      }
    });
    
    // 移除scroll事件监听 - 每次滚动都强制scrollTop会导致严重卡顿
    // 仅在键盘弹出时通过resize事件处理滚动
  }
  
  window.addEventListener('resize',function(){
    var newHeight=window.innerHeight;
    var heightDiff=originalHeight-newHeight;
    
    if(heightDiff>50){
      if(msgbox){
        setTimeout(function(){msgbox.scrollTop=msgbox.scrollHeight},100);
      }
    }
  });
  
  document.addEventListener('focusin',function(e){
    if(e.target.tagName==='TEXTAREA'||e.target.tagName==='INPUT'){
      setTimeout(function(){
        if(msgbox){
          msgbox.scrollTop=msgbox.scrollHeight;
        }
      },300);
    }
  });
}
