var contacts=[],groups=[],me={name:'我',avatar:'',wxid:'',momentsCover:''},cid=null,rtimers={},typingStates={},currentProfileContactId=null,emotionStreak=0;
var cardPrivateContacts=[];

function loadCardPrivateContacts(){
  try{
    var stored=localStorage.getItem('ml2_card_private_contacts');
    if(stored){
      cardPrivateContacts=JSON.parse(stored);
    }
  }catch(e){
    cardPrivateContacts=[];
  }
  // 异步从 IndexedDB 恢复并合并，防止 localStorage 丢失导致绑定数据为空
  // ★ 修复：以 localStorage 为最新（保存是同步成功的），IndexedDB 只补充缺失项，
  // 避免 IndexedDB 旧数据（未绑定）覆盖 localStorage 新绑定
  if(window.localforage){
    window.localforage.getItem('ml2_card_private_contacts').then(function(dbVal){
      if(dbVal){
        try{
          var dbData=typeof dbVal==='string'?JSON.parse(dbVal):dbVal;
          if(Array.isArray(dbData)&&dbData.length>0){
            // 以 localStorage 为准合并：localStorage 已有 id 保留（含最新绑定），IndexedDB 只补充缺失
            var merged=cardPrivateContacts.slice();
            var seen={};
            merged.forEach(function(pc){if(pc&&pc.id)seen[pc.id]=true;});
            var added=false;
            dbData.forEach(function(pc){
              if(pc&&pc.id&&!seen[pc.id]){seen[pc.id]=true;merged.push(pc);added=true;}
            });
            // 若 IndexedDB 有而 localStorage 没有的条目，且带绑定信息，则保留（可能 localStorage 丢失）
            if(merged.length!==cardPrivateContacts.length){
              cardPrivateContacts=merged;
              try{localStorage.setItem('ml2_card_private_contacts',JSON.stringify(cardPrivateContacts));}catch(e){}
            }
            if(added)console.log('loadCardPrivateContacts: merged',added,'from IndexedDB');
          }
        }catch(e){console.warn('loadCardPrivateContacts: IndexedDB merge failed',e);}
      }
    }).catch(function(e){console.warn('loadCardPrivateContacts: IndexedDB read failed',e);});
  }
}

function saveCardPrivateContacts(){
  try{
    var serialized=JSON.stringify(cardPrivateContacts);
    localStorage.setItem('ml2_card_private_contacts',serialized);
  }catch(e){}
  // 同步写入 IndexedDB，确保数据持久化不丢失；失败时重试一次
  if(window.localforage){
    window.localforage.setItem('ml2_card_private_contacts',serialized).then(function(){
      try{localStorage.setItem('ml2_card_private_contacts_synced',String(Date.now()));}catch(e){}
    }).catch(function(e){
      console.warn('saveCardPrivateContacts: IndexedDB save failed, retrying',e);
      setTimeout(function(){
        if(window.localforage){window.localforage.setItem('ml2_card_private_contacts',serialized).catch(function(){});}
      },500);
    });
  }
}
