var DEFAULT_COMMON_CARDS=[];
(function(){
  var lines=_DCCT.split('\n');
  var curIdx=-1;
  var cardId=0;
  for(var i=0;i<lines.length;i++){
    var line=lines[i].replace(/\r$/,'').trim();
    if(!line)continue;
    var m=line.match(/^【([^】]+)】$/);
    if(m){
      curIdx=-1;
      for(var j=0;j<DEFAULT_COMMON_GROUPS.length;j++){
        if(DEFAULT_COMMON_GROUPS[j].name===m[1]){curIdx=j;break;}
      }
      continue;
    }
    if(curIdx<0)continue;
    DEFAULT_COMMON_CARDS.push({id:'dc_'+cardId,content:line,type:'public',category:'custom',groupId:'g_def_'+curIdx,contactId:null});
    cardId++;
  }
})();

