function compressImage(file,maxSize,quality,callback){if(file.type==='image/gif'||(file.name&&file.name.toLowerCase().endsWith('.gif'))){var reader=new FileReader();reader.onload=function(e){callback(e.target.result)};reader.onerror=function(){callback('')};reader.readAsDataURL(file);return}var img=new Image();img.onload=function(){try{var canvas=document.createElement('canvas');var ctx=canvas.getContext('2d',{alpha:true});if(!ctx){callback('');URL.revokeObjectURL(img.src);return}var ratio=Math.min(maxSize/img.width,maxSize/img.height,1);canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(img,0,0,canvas.width,canvas.height);var mimeType=(file.type&&file.type.indexOf('png')>-1)?'image/png':(file.type&&file.type.indexOf('gif')>-1?'image/gif':'image/jpeg');try{var dataUrl=canvas.toDataURL(mimeType,quality);callback(dataUrl)}catch(e){console.warn('compressImage toDataURL failed:',e);callback('')}URL.revokeObjectURL(img.src);canvas.width=0;canvas.height=0;canvas=null;ctx=null}catch(e){console.warn('compressImage failed:',e);callback('');URL.revokeObjectURL(img.src)}};img.onerror=function(){callback('');URL.revokeObjectURL(img.src)};img.src=URL.createObjectURL(file)}

