function refreshNavDisplay(){
  if(!cid)return;
  var state=navDisplayStates[cid];
  var isGroup=window.currentConvType==='group';
  if(state){
    if(state.weather&&$('nav-weather')){
      $('nav-weather').textContent=state.weather;
      $('nav-weather').style.display=isGroup?'none':'';
    }
    if(state.time&&$('nav-time')){
      $('nav-time').textContent=state.time;
      $('nav-time').style.display=isGroup?'none':'';
    }
    if(state.status&&$('nav-contact-status')){
      $('nav-contact-status').textContent=state.status;
      var c2=contacts.find(function(x){return x.id===cid});
      var hideStatus2=!!(c2&&c2.hideTopbarAvatarStatus);
      $('nav-contact-status').style.display=(isGroup||hideStatus2)?'none':'';
    }
    if(state.idle&&$('nav-idle')){
      $('nav-idle').textContent=state.idle;
      $('nav-idle').style.display=isGroup?'none':'';
    }
    if(state.mood&&$('nav-mood')){
      $('nav-mood').textContent=state.mood;
      $('nav-mood').style.display=isGroup?'none':'';
    }
    // 同步更新顶部栏头像（联系人随机头像库更换时）
    if(!isGroup&&$('nav-contact-avatar')){
      var currentContact=contacts.find(function(x){return x.id===cid});
      var avatarHtml='';
      if(currentContact&&currentContact.avatar){avatarHtml='<img src="'+currentContact.avatar.replace(/"/g,'&quot;')+'">';}
      else{avatarHtml='✦';}
      $('nav-contact-avatar').innerHTML=avatarHtml;
    }
  }
}

async function checkNavDisplay(){
  for(var i=0;i<contacts.length;i++){
    var c=contacts[i];
    if(!navDisplayStates[c.id]){
      navDisplayStates[c.id]={
        lastStatusChange:0,
        nextStatusChange:0,
        lastWeatherChange:0,
        nextWeatherChange:0,
        lastTimeChange:0,
        nextTimeChange:0,
        lastIdleChange:0,
        nextIdleChange:0,
        lastMoodChange:0,
        nextMoodChange:0
      };
    }
    var state=navDisplayStates[c.id];
    if(state.lastStatusChange===undefined||state.lastStatusChange===null||state.lastStatusChange>Date.now()){
      state.lastStatusChange=0;
      state.nextStatusChange=0;
    }
    if(state.lastWeatherChange===undefined||state.lastWeatherChange===null||state.lastWeatherChange>Date.now()){
      state.lastWeatherChange=0;
      state.nextWeatherChange=0;
    }
    if(state.lastTimeChange===undefined||state.lastTimeChange===null||state.lastTimeChange>Date.now()){
      state.lastTimeChange=0;
      state.nextTimeChange=0;
    }
    if(state.lastIdleChange===undefined||state.lastIdleChange===null||state.lastIdleChange>Date.now()){
      state.lastIdleChange=0;
      state.nextIdleChange=0;
    }
    if(state.lastMoodChange===undefined||state.lastMoodChange===null||state.lastMoodChange>Date.now()){
      state.lastMoodChange=0;
      state.nextMoodChange=0;
    }
    
    if((Date.now()-state.lastStatusChange)/36e5>=state.nextStatusChange){
      await updateNavContactStatus(c);
      state.lastStatusChange=Date.now();
      state.nextStatusChange=1+Math.random()*7;
    }
    
    if((Date.now()-state.lastWeatherChange)/36e5>=state.nextWeatherChange){
      await updateNavWeather(c.id);
      state.lastWeatherChange=Date.now();
      state.nextWeatherChange=1+Math.random()*7;
    }
    
    if((Date.now()-state.lastTimeChange)/36e5>=state.nextTimeChange){
      await updateNavTime(c.id);
      state.lastTimeChange=Date.now();
      state.nextTimeChange=1+Math.random()*7;
    }
    
    if((Date.now()-state.lastIdleChange)/36e5>=state.nextIdleChange){
      await updateNavIdle(c.id);
      state.lastIdleChange=Date.now();
      state.nextIdleChange=1+Math.random()*7;
    }
    
    if((Date.now()-state.lastMoodChange)/36e5>=state.nextMoodChange){
      await updateNavMood(c.id);
      state.lastMoodChange=Date.now();
      state.nextMoodChange=1+Math.random()*7;
    }
  }
  await saveNavDisplayStates();
}

// setInterval(checkNavDisplay,60000); // 移到初始化完成后启动

async function updateNavContactStatus(contact){
  if(!navDisplayStates[contact.id]){
    navDisplayStates[contact.id]={};
  }
  var publicCards=await getNavCards('public');
  var privateCards=await getNavCards('private',contact.id);
  var statusCards=publicCards.filter(function(c){return c.category==='status'}).concat(
    privateCards.filter(function(c){return c.category==='status'})
  );
  var statusText='在线';
  if(statusCards.length>0){
    var lastIndex=navDisplayStates[contact.id].lastStatusIndex||-1;
    var newIndex;
    do{
      newIndex=Math.floor(Math.random()*statusCards.length);
    }while(statusCards.length>1&&newIndex===lastIndex);
    navDisplayStates[contact.id].lastStatusIndex=newIndex;
    statusText=statusCards[newIndex].content;
  }
  navDisplayStates[contact.id].status=statusText;
  navDisplayStates[contact.id].lastStatusChange=Date.now();
  await saveNavDisplayStates();
  if(cid===contact.id&&$('nav-contact-status')){
    $('nav-contact-status').textContent=statusText;
    var hideTopStatus=!!(contact&&contact.hideTopbarAvatarStatus);
    $('nav-contact-status').style.display=hideTopStatus?'none':'';
  }
}

function handleReplyMsg(msgId){
  var m=msgs(cid);
  var msg=m.find(function(m){return m.id===msgId});
  if(!msg)return;
  replyingToMsg=msgId;
  var content='';
  var replyContact=contacts.find(function(x){return x.id===cid});
  if(msg.retracted){
    content='对方撤回了一条消息';
  }else if(msg.isTouch){
    var _hideTouchReply=_globalHideTouchNames[cid]===true;
    if(!_hideTouchReply&&getHideTouchNames(cid)===true){
      _hideTouchReply=true;
    }
    if(!_hideTouchReply&&typeof editingContact!=='undefined'&&editingContact&&editingContact.id===cid&&editingContact.hideTouchNames){
      _hideTouchReply=true;
    }
    if(!_hideTouchReply){
      var touchContact=contacts.find(function(ct){return ct.id===cid});
      _hideTouchReply=!!(touchContact&&touchContact.hideTouchNames);
    }
    var touchName=(msg.s===SELF?'我':(_hideTouchReply?'TA':(msg.senderName||'对方')));
    var replyTouchAction=msg.touchAction||'';
    if(_hideTouchReply&&replyContact&&replyContact.name){
      replyTouchAction=replyTouchAction.replace(new RegExp(replyContact.name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'g'),msg.s===SELF?'TA':'我');
    }
    var replyTouchTarget=msg.touchTarget||'你';
    if(_hideTouchReply){
      replyTouchTarget=msg.s===SELF?'TA':'我';
    }
    var touchContent=touchName+' '+replyTouchAction.replace('你',replyTouchTarget);
    content='<span style="font-size:12px;color:var(--txt2)">'+touchContent+'</span>';
  }else if(msg.img){
    var replyImgUrl=msg.img;
    if(replyImgUrl&&!replyImgUrl.startsWith('data:image/')){
      var cachedReplyImg=memoryCache['_img_'+replyImgUrl];
      if(cachedReplyImg)replyImgUrl=cachedReplyImg;
    }
    var isSticker=msg.isSticker===true;
    var imgClass=isSticker?'message-sticker':'message-img';
    content='<img src="'+replyImgUrl.replace(/"/g,'&quot;')+'" class="'+imgClass+'" style="max-width:60px;max-height:60px;border-radius:6px;object-fit:cover;">';
  }else if(msg.t){
    content=msg.t;
  }else{
    content='[消息]';
  }
  if(!msg.img&&content.length>30)content=content.substring(0,30)+'...';
  $('quote-preview-content').innerHTML=content;
  $('quote-preview').style.display='flex';
}

function handleDeleteMsg(msgId){
  customConfirm('确定删除这条消息吗？').then(function(ok){
    if(!ok)return;
    var m=msgs(cid);
    m=m.filter(function(m){return m.id!==msgId});
    savemsgs(cid,m);
    renderMsgs();
    haptic('warn');
  });
}

function handleRetractMsg(msgId){
  customConfirm('确定撤回这条消息吗？').then(function(ok){
    if(!ok)return;
    var m=msgs(cid);
    var msg=m.find(function(m){return m.id===msgId});
    if(msg){
      msg.retracted=true;
      msg.originalContent=msg.t;
      msg.originalImg=msg.img;
      msg.t='';
      msg.img='';
      savemsgs(cid,m);
      renderMsgs();
      haptic('light');
      toast('消息已撤回');
    }
  });
}

function handleEditMsg(msgId){
  var m=msgs(cid);
  var msg=m.find(function(m){return m.id===msgId});
  if(msg&&msg.t&&msg.s===SELF){
    var newText=prompt('编辑消息内容：',msg.t);
    if(newText!==null&&newText!==msg.t){
      msg.t=newText;
      savemsgs(cid,m);
      renderMsgs();
      toast('消息已编辑');
    }
  }else if(msg&&msg.t&&msg.s!==SELF){
    toast('只能编辑自己发送的消息');
  }else{
    toast('此消息无法编辑');
  }
}

function fallbackCopy(text){
  var textarea=document.createElement('textarea');
  textarea.value=text;
  textarea.style.position='fixed';
  textarea.style.left='-9999px';
  textarea.style.top='-9999px';
  textarea.style.opacity='0';
  document.body.appendChild(textarea);
  textarea.select();
  try{
    var successful=document.execCommand('copy');
    if(successful){
      toast('已复制到剪贴板');
    }else{
      toast('复制失败');
    }
  }catch(err){
    toast('复制失败');
  }
  document.body.removeChild(textarea);
}

function showMsgActionMenu(x,y,msgId,isLiked,isNonInstant){
  document.removeEventListener('click',hideMsgActionMenuOnce);
  var menu=$('msg-action-menu');
  var replyBtn=$('msg-action-reply');
  var editBtn=$('msg-action-edit');
  var retractBtn=$('msg-action-retract');
  var copyBtn=$('msg-action-copy');
  var deleteBtn=$('msg-action-delete');
  
  var getMsgs=function(){return isNonInstant?nonInstantMsgs(nonInstantCid):msgs(cid)};
  var saveMsgs=function(id,m){return isNonInstant?saveNonInstantMsgs(id,m):savemsgs(id,m)};
  var renderMsgsFunc=function(){return isNonInstant?renderNonInstantMsgs():renderMsgs()};
  var currentId=isNonInstant?nonInstantCid:cid;
  
  var msg=getMsgs().find(function(m){return m.id===msgId});
  var isSelf=msg&&msg.s===SELF;
  
  replyBtn.style.display='flex';
  deleteBtn.style.display='flex';
  
  if(isSelf){
    editBtn.style.display='flex';
    retractBtn.style.display='flex';
    copyBtn.style.display='none';
  }else{
    editBtn.style.display='none';
    retractBtn.style.display='none';
    copyBtn.style.display='none';
  }
  
  replyBtn.onclick=function(e){e.stopPropagation();
    var msg=getMsgs().find(function(m){return m.id===msgId});
    if(!msg){hideMsgActionMenu();return;}
    replyingToMsg=msgId;
    var content='';
    if(msg.retracted){
      content='对方撤回了一条消息';
    }else if(msg.img){
      var actionImgUrl=msg.img;
      if(actionImgUrl&&!actionImgUrl.startsWith('data:image/')){
        var cachedActionImg=memoryCache['_img_'+actionImgUrl];
        if(cachedActionImg)actionImgUrl=cachedActionImg;
      }
      var isSticker=msg.isSticker===true;
      var imgClass=isSticker?'message-sticker':'message-img';
      content='<img src="'+actionImgUrl.replace(/"/g,'&quot;')+'" class="'+imgClass+'" style="max-width:60px;max-height:60px;border-radius:6px;object-fit:cover;">';
    }else if(msg.t){
      content=msg.t;
    }else{
      content='[消息]';
    }
    if(!msg.img&&content.length>30)content=content.substring(0,30)+'...';
    $('quote-preview-content').innerHTML=content;
    $('quote-preview').style.display='flex';
    hideMsgActionMenu();
  };
  
  editBtn.onclick=function(e){e.stopPropagation();
    var m=getMsgs();
    var msg=m.find(function(m){return m.id===msgId});
    if(msg&&msg.t&&msg.s===SELF){
      var newText=prompt('编辑消息内容：',msg.t);
      if(newText!==null&&newText!==msg.t){
        msg.t=newText;
        saveMsgs(currentId,m);
        renderMsgsFunc();
        toast('消息已编辑');
      }
    }else if(msg&&msg.t&&msg.s!==SELF){
      toast('只能编辑自己发送的消息');
    }else{
      toast('此消息无法编辑');
    }
    hideMsgActionMenu();
  };
  
  retractBtn.onclick=function(e){e.stopPropagation();
    var m=getMsgs();
    var msg=m.find(function(m){return m.id===msgId});
    if(msg&&msg.s===SELF){
      msg.retracted=true;
      msg.originalText=msg.t;
      msg.t='';
      saveMsgs(currentId,m);
      renderMsgsFunc();
      toast('消息已撤回');
      haptic('light');
    }else{
      toast('只能撤回自己发送的消息');
    }
    hideMsgActionMenu();
  };
  
  copyBtn.onclick=function(e){e.stopPropagation();
    var msg=getMsgs().find(function(m){return m.id===msgId});
    if(msg){
      if(msg.t){
        if(navigator.clipboard&&navigator.clipboard.writeText){
          navigator.clipboard.writeText(msg.t).then(function(){
            toast('已复制到剪贴板');
          }).catch(function(){
            fallbackCopy(msg.t);
          });
        }else{
          fallbackCopy(msg.t);
        }
      }else if(msg.img){
        var img=new Image();
        img.crossOrigin='anonymous';
        img.onload=function(){
          var canvas=document.createElement('canvas');
          canvas.width=img.width;
          canvas.height=img.height;
          var ctx=canvas.getContext('2d');
          ctx.drawImage(img,0,0);
          canvas.toBlob(function(blob){
            if(blob){
              navigator.clipboard.write([new ClipboardItem({'image/png':blob})]).then(function(){
                toast('图片已复制到剪贴板');
              }).catch(function(){
                toast('复制失败，请手动保存图片');
              });
            }
          },'image/png');
        };
        img.onerror=function(){
          toast('无法复制此图片');
        };
        img.src=msg.img;
      }else{
        toast('没有可复制的内容');
      }
    }
    hideMsgActionMenu();
  };
  
  var doDeleteAction=function(e){e.stopPropagation();
    customConfirm('确定删除这条消息吗？').then(function(ok){
      if(!ok){hideMsgActionMenu();return}
      var m=getMsgs();
      m=m.filter(function(m){return m.id!==msgId});
      saveMsgs(currentId,m);
      renderMsgsFunc();
      haptic('warn');
      hideMsgActionMenu();
    });
  };
  deleteBtn.onclick=doDeleteAction;
  deleteBtn.ontouchend=function(e){e.preventDefault();doDeleteAction(e)};
  
  var menuWidth=menu.offsetWidth||200;
  var menuHeight=menu.offsetHeight||40;
  var maxX=window.innerWidth-menuWidth-10;
  var maxY=window.innerHeight-menuHeight-10;
  var finalX=Math.max(10,Math.min(x,maxX));
  var finalY=Math.max(10,Math.min(y,maxY));
  menu.style.left=finalX+'px';
  menu.style.top=finalY+'px';
  menu.style.display='flex';
  
  setTimeout(function(){
    document.addEventListener('click',hideMsgActionMenuOnce);
    document.addEventListener('touchstart',hideMsgActionMenuOnce);
  }, 0);
}

function hideMsgActionMenu(){
  var el=$('msg-action-menu');if(el)el.style.display='none';
}

function hideMsgActionMenuOnce(e){
  var el=$('msg-action-menu');if(!el||!el.contains(e.target)){
    hideMsgActionMenu();
    document.removeEventListener('click',hideMsgActionMenuOnce);
    document.removeEventListener('touchstart',hideMsgActionMenuOnce);
  }
}
function showRetractedContent(el){
  var original=el.nextElementSibling;
  if(original&&original.classList.contains('retracted-original')){
    original.style.display=original.style.display==='none'?'block':'none';
  }
};
// ===== 批量发送模式 =====
var isBatchMode = false;
var batchMessages = [];

function toggleBatchMode() {
  isBatchMode = !isBatchMode;
  var batchBtn = $('batch-btn');
  var batchPreview = $('batch-preview');
  var msgInp = $('msg-inp');
  
  if (isBatchMode) {
    if (batchBtn) batchBtn.classList.add('active');
    if (batchBtn) batchBtn.title = '退出批量模式';
    if (batchPreview) { batchPreview.classList.add('show'); batchPreview.style.display = 'flex'; }
    batchMessages = [];
    if (msgInp) msgInp.placeholder = '此刻，想说的有很多很多...';
    updateBatchPreview();
  } else {
    if (batchBtn) batchBtn.classList.remove('active');
    if (batchBtn) batchBtn.title = '批量发送模式';
    if (batchPreview) { batchPreview.classList.remove('show'); batchPreview.style.display = 'none'; }
    batchMessages = [];
    if (msgInp) msgInp.placeholder = '输入消息...';
  }
  updateSendBtn();
}

function addToBatch() {
  var inp = $('msg-inp');
  var t = inp.value.trim();
  if (!t) return;
  
  batchMessages.push({
    id: Date.now() + '_' + batchMessages.length,
    text: t,
    type: 'text'
  });
  
  inp.value = '';
  inp.style.height = 'auto';
  updateBatchPreview();
  updateSendBtn();
  haptic('light');
}

function updateBatchPreview() {
  var preview = $('batch-preview');
  if (!preview) return;
  
  var listHTML = '';
  if (batchMessages.length > 0) {
    listHTML = batchMessages.map(function(msg, index) {
      if (msg.type === 'image') {
        var imgSrc = msg.originalImage || msg.image;
        return '<div class="batch-preview-item" data-index="' + index + '">' +
          '<img src="' + imgSrc + '" style="width:60px;height:60px;border-radius:8px;object-fit:cover;flex-shrink:0;">' +
          '<span class="batch-preview-text">图片</span>' +
          '<button class="batch-preview-remove">×</button>' +
        '</div>';
      }
      return '<div class="batch-preview-item" data-index="' + index + '">' +
        '<span class="batch-preview-text">' + escapeHtml(msg.text) + '</span>' +
        '<button class="batch-preview-remove">×</button>' +
      '</div>';
    }).join('');
  } else {
    listHTML = '<div style="text-align:center;color:var(--txt3);font-size:12px;padding:10px;">暂无消息</div>';
  }
  
  preview.innerHTML = 
    '<div class="batch-preview-title">' +
      '<span style="font-size:10px;color:var(--txt4);">批量发送：支持一次输入多条消息内容，并按照顺序逐条发送到聊天记录中（群友想要，借鉴milk老师的字卡功能搓了，总之感谢milk老师）</span>' +
      '<button class="batch-add-img-btn" id="batch-add-img-btn" title="添加图片">🖼️</button>' +
    '</div>' +
    '<div class="batch-preview-list">' + listHTML + '</div>' +
    '<div class="batch-actions">' +
      '<button class="batch-action-btn batch-cancel-btn">取消</button>' +
      '<button class="batch-action-btn batch-send-btn"' + (batchMessages.length === 0 ? ' disabled' : '') + '>发送全部 (' + batchMessages.length + ')</button>' +
    '</div>';
}

function sendBatchMessages() {
  if (batchMessages.length === 0) return;
  if (!cid) { toast('请先选择联系人'); return; }
  
  toast('正在发送 ' + batchMessages.length + ' 条消息...');
  
  var totalDelay = batchMessages.length * 300;
  
  batchMessages.forEach(function(msg, index) {
    setTimeout(function() {
      var m = msgs(cid);
      if (msg.type === 'image') {
        var msgObj = {
          id: 'm_' + Date.now() + '_' + index + '_' + Math.random().toString(36).substr(2, 5),
          s: SELF,
          t: '',
          img: msg.image,
          ts: new Date(),
          pc: false,
          isSticker: false,
          isGroup: window.currentConvType === 'group',
          read: true,
          senderName: '我',
          senderId: me.id
        };
        m.push(msgObj);
      } else {
        var msgObj = {
          id: 'm_' + Date.now() + '_' + index + '_' + Math.random().toString(36).substr(2, 5),
          s: SELF,
          t: msg.text,
          ts: new Date(),
          pc: false,
          isGroup: window.currentConvType === 'group',
          read: true,
          senderName: '我',
          senderId: me.id
        };
        m.push(msgObj);
      }
      savemsgs(cid, m);
      renderMsgs(m);
      var msgbox=$('msgbox');if(msgbox)msgbox.scrollTop=msgbox.scrollHeight;
      
      if (index === batchMessages.length - 1) {
        renderChatList();
      }
      
      playSound('send', cid);
    }, index * 300);
  });
  
  // 统一调度回复
  setTimeout(function() {
    if (!pomodoroState.isRunning || !pomodoroState.isPaused || !pomodoroSettings.blockDuringFocus) {
      scheduleReply();
    }
  }, totalDelay);
  
  // 退出批量模式
  isBatchMode = false;
  batchMessages = [];
  var batchBtn = $('batch-btn');
  var batchPreview = $('batch-preview');
  var msgInp = $('msg-inp');
  if (batchBtn) batchBtn.classList.remove('active');
  if (batchPreview) { 
    batchPreview.classList.remove('show'); 
    batchPreview.style.display = 'none';
    batchPreview.innerHTML = '';
  }
  if (msgInp) {
    msgInp.placeholder = '输入消息...';
    msgInp.value = '';
    msgInp.style.height = '36px';
  }
  updateSendBtn();
}

function sendMsg(){
  if(!cid)return;
  if(isBatchMode){addToBatch();return;}
  var inp=$('msg-inp'),t=inp.value.trim();
  if(pendingImages.length>0){
    var imgs=pendingImages.slice();
    pendingImages=[];
    renderPendingImages('inline-image-bar','iith_');
    var m=msgs(cid);
    var msg={id:'m_'+Date.now()+'_'+Math.random().toString(36).substr(2,9),s:SELF,t:t||'',imgs:imgs,img:imgs.length===1?imgs[0]:'',ts:new Date(),pc:false,quote:replyingToMsg,isGroup:window.currentConvType==='group',read:true,senderName:'我',senderId:me.id,isSticker:false};
    m.push(msg);
    savemsgs(cid,m);
    inp.value='';inp.style.height='36px';replyingToMsg=null;$('quote-preview').style.display='none';
    renderMsgs(m);updateSendBtn();renderChatList();scheduleReply();playSound('send',cid);haptic('light');simulateTAFavorite();
    return;
  }
  if(!t)return;
  var m2=msgs(cid);var msg2={id:'m_'+Date.now()+'_'+Math.random().toString(36).substr(2,9),s:SELF,t:t,ts:new Date(),pc:false,quote:replyingToMsg,isGroup:window.currentConvType==='group',read:true,senderName:'我',senderId:me.id};m2.push(msg2);savemsgs(cid,m2);inp.value='';inp.style.height='36px';replyingToMsg=null;$('quote-preview').style.display='none';renderMsgs(m2);updateSendBtn();renderChatList();scheduleReply();playSound('send',cid);haptic('light');simulateTAFavorite();
}
function updateSendBtn(){var inp=$('msg-inp'),s=$('btn-send');if(inp.value.trim().length>0||pendingImages.length>0){s.classList.remove('disabled')}else{s.classList.add('disabled')}}
function scheduleReply(){if(!cid||cid==='fh')return;if(isBatchMode)return;if(pomodoroState.isRunning&&!pomodoroState.isPaused&&pomodoroSettings.blockDuringFocus)return;var rsMin=getSpeed('rs-min',cid),rsMax=getSpeed('rs-max',cid),rnProb=getSpeed('rn-prob',cid);var targetId=cid;var msgbox=$('msgbox');if(msgbox)msgbox.scrollTop=msgbox.scrollHeight;if(Math.random()*100<rnProb){rtimers[targetId]=setTimeout(function(){markMessageReadIgnored(targetId)},(1+Math.random()*3)*1000);return}typingStates[targetId]=true;if(cid===window.currentCid){var typingEl=$('typing');if(typingEl)typingEl.style.display='flex';}var delay=(rsMin+Math.random()*(rsMax-rsMin))*1000;if(rtimers[targetId])clearTimeout(rtimers[targetId]);rtimers[targetId]=setTimeout(function(){var group=groups.find(function(g){return g.id===targetId});var isGroup=!!group;if(isGroup){/* For group chats, keep typing indicator visible until all members respond */genReply(targetId);}else{typingStates[targetId]=false;if(targetId===window.currentCid){var typingEl2=$('typing');if(typingEl2)typingEl2.style.display='none';}genReply(targetId)}},delay)}
function markMessageReadIgnored(targetId,silent){
  var m=msgs(targetId);
  if(m.length===0)return;
  var lastSelfMsg=m.filter(function(msg){return msg.s===SELF}).pop();
  if(lastSelfMsg){
    lastSelfMsg.readIgnored=silent?'touch':true;
    savemsgs(targetId,m);
    if(targetId===window.currentCid)renderMsgs(m);
    renderChatList();
  }
}



async function genReply(targetId){
  if(!targetId)targetId=cid;
  if(!targetId)return;

  // ★ 修复：确保用户自己的字卡（globalCards）已加载，避免点【让对方继续说】时
  // globalCards 未加载导致只剩默认通用字卡（用户自己的公用/专享字卡没进池）
  if(typeof globalCards==='undefined'||!globalCards||globalCards.length===0){
    try{
      if(typeof loadGlobalCards==='function'){await loadGlobalCards();}
    }catch(e){console.warn('genReply loadGlobalCards failed:',e);}
  }

  if(!currentCall){
    checkIncomingCall();
  }
  
  var group=groups.find(function(g){return g.id===targetId});
  var isGroup=!!group;
  var senderId=targetId;
  var senderName='';
  
  if(isGroup){
    var groupMsgs=msgs(targetId);
    var hasUserSpoken=groupMsgs.some(function(msg){return msg.s===SELF});
    if(!hasUserSpoken){
      typingStates[targetId]=false;
      if(targetId===window.currentCid){var typingEl0=$('typing');if(typingEl0)typingEl0.style.display='none';}
      return;
    }
    
    var otherMembers=group.memberIds.filter(function(id){return id!==me.id});
    if(otherMembers.length===0){
      typingStates[targetId]=false;
      if(targetId===window.currentCid){var typingEl0=$('typing');if(typingEl0)typingEl0.style.display='none';}
      return;
    }
    
    // 遍历所有成员，根据每个成员的概率设置决定是否回复
    var selectedMembers=[];
    for(var i=0;i<otherMembers.length;i++){
      var memberId=otherMembers[i];
      // 获取该成员的群聊回复概率
      var pyEn=getSpeed('py-en',memberId);
      var pyProb=getSpeed('py-prob',memberId);
      
      // 检查是否启用了回复功能
      if(pyEn===0||pyEn===false){
        continue; // 该成员未启用群聊回复
      }
      
      // 根据概率决定是否回复
      if(Math.random()*100<pyProb){
        selectedMembers.push(memberId);
      }
    }
    
    // 如果没有成员命中概率，至少选择1个成员回复（使用全局默认概率）
    if(selectedMembers.length===0){
      var defaultProb=getSpeed('py-prob');
      // 如果默认概率为0或未设置，则随机选择一个成员
      if(defaultProb<=0){
        selectedMembers=[otherMembers[Math.floor(Math.random()*otherMembers.length)]];
      }
      // 否则保持为空，没有成员回复
    }
    
    // Clear typing indicator after the last member's reply
    var totalMembers=selectedMembers.length;
    if(totalMembers===0){
      typingStates[targetId]=false;
      if(targetId===window.currentCid){var typingEl0=$('typing');if(typingEl0)typingEl0.style.display='none';}
      return;
    }
    
    var completedCount=0;
    var onMemberComplete=function(){
      completedCount++;
      if(completedCount>=totalMembers){
        typingStates[targetId]=false;
        if(targetId===window.currentCid){var typingEl=$('typing');if(typingEl)typingEl.style.display='none';}
      }
    };
    
    // Generate replies for each selected member with staggered delays
    var baseDelay=0;
    for(var idx=0;idx<selectedMembers.length;idx++){
      // 获取该成员的等待时间设置
      var rsMin=getSpeed('rs-min',selectedMembers[idx])*1000;
      var rsMax=getSpeed('rs-max',selectedMembers[idx])*1000;
      var memberDelay=rsMin+Math.random()*(rsMax-rsMin);
      
      (function(memberId,delay){
        setTimeout(async function(){
          try{
            await genSingleMemberReply(targetId,memberId,group);
          }finally{
            onMemberComplete();
          }
        },delay);
      })(selectedMembers[idx],baseDelay+memberDelay);
      
      baseDelay+=500; // 成员之间错开500ms
    }
    return;
  }
  
  // Non-group chat: single reply
  if(group&&group.memberIds&&group.memberIds.length>0){
    var allMembers=group.memberIds;
    senderId=allMembers[Math.floor(Math.random()*allMembers.length)];
  }
  var sender=contacts.find(function(c){return c.id===senderId});
  var baseName=sender?sender.name:'未知';
  senderName=baseName;
  
  await genSingleMemberReply(targetId,senderId,null,senderName);
}

async function genSingleMemberReply(targetId,senderId,group,preComputedSenderName){
  var isGroup=!!group;
  var senderName=preComputedSenderName||'';
  
  if(isGroup){
    var sender=contacts.find(function(c){return c.id===senderId});
    var baseName=sender?sender.name:'未知';
    var groupNickname=group.memberSettings&&group.memberSettings[senderId]&&group.memberSettings[senderId].nickname||'';
    senderName=groupNickname||baseName;
  }
  
  if(!senderId||senderId===me.id)return;
  
  var touchProb=getSpeed('touch-prob',senderId);
  if(touchProb>0&&Math.random()*100<touchProb){
    contactPerformTouch(targetId);
    return;
  }
  // ★ 修复：默认通用字卡的【拍一拍】只在用户明确选择拍一拍时触发（不发普通文字）
  // 注意：不再因 defaultCommonEnabled 开关而随机触发，避免把正常字卡回复变成拍一拍
  try{
    if(typeof _fallbackDefaultCat!=='undefined'&&_fallbackDefaultCat==='touch'){
      var _dcTouchProb=defaultCommonProbs&&defaultCommonProbs.touch!=null?defaultCommonProbs.touch:30;
      if(Math.random()*100<_dcTouchProb){
        var _dcTouchCards=typeof getDefaultTouchCards==='function'?getDefaultTouchCards():[];
        if(_dcTouchCards.length>0){
          contactPerformTouch(targetId);
          return;
        }
      }
    }
  }catch(e){console.warn('default touch check failed:',e);}
  
  var userCards=globalCards.filter(function(card){
    if(!card)return false;
    if(!card.content)return false;
    if(card.category!=='stickers'&&card.category!=='voices'&&(!card.content.trim()))return false;
    if(card.category==='touch')return false;
    if(card.groupId){
      var cg=cardGroups.find(function(g){return g.id===card.groupId});
      if(cg&&cg.disabled)return false;
      if(cg&&cg.type==='public'&&cg.disabledContacts&&cg.disabledContacts.indexOf(senderId)>=0)return false;
    }
    if(card.type==='public')return true;
    if(card.type==='private'){
      if(card.contactId===senderId)return true;
      var pc=cardPrivateContacts.find(function(p){return p.id===card.contactId&&p.bindContactId===senderId});
      if(pc)return true;
    }
    if(!card.type)return true;
    return false;
  });
  
  // 构建可用字卡池（只有用户自己的字卡）
  var availableCards=userCards.slice();
  
  // ★ 修复：默认通用字卡（11007条）不混入池——否则数量占绝对多数，几乎必然抽到默认字卡。
  // 改为独立判定：按"整体出现概率"决定本次回复是否用默认字卡；用则单独从默认字卡抽。
  var _useDefaultOnly=false;
  if(defaultCommonEnabled&&defaultCommonAllContacts&&defaultCommonUseChat){
    if(availableCards.length===0){
      // 没有自己的字卡：默认字卡兜底（仍受整体概率控制）
      var _dc0=getDefaultCommonCardsForContact(senderId);
      if(_dc0&&_dc0.length>0){
        availableCards=_dc0.map(function(text){return {content:text,category:'custom',type:'default_common',groupId:null};});
        _useDefaultOnly=true;
      }
    }
    // 有自己的字卡：默认字卡不进池，由后面的独立概率逻辑决定是否用默认字卡
  }
  
  // ★ 兜底：既没有自己的字卡，默认字卡也没触发 → 发提示
  if(!availableCards.length){
    try{
      var _fbCards=getDefaultCommonCardsForContact(senderId);
      if(_fbCards&&_fbCards.length>0){
        availableCards=_fbCards.map(function(text){return {content:text,category:'custom',type:'default_common',groupId:null};});
        _useDefaultOnly=true;
      }
    }catch(e){console.warn('fallback default cards failed:',e);}
  }
  
  if(!availableCards.length){
    if(isGroup)return; // Skip group members with no cards silently
    var m=msgs(targetId);
    if(!m||m.length===0){console.warn('genReply: msgs empty for',targetId,', skip');return;}
    var replyMsg={id:'m_'+Date.now()+'_'+Math.random().toString(36).substr(2,9),s:OTHER,t:'请在字卡库里上传字卡后开始聊天',img:'',voice:'',voiceText:'',ts:new Date(),pc:false,isAuto:true,isInitiative:false,quote:null,isSticker:false,isVoice:false,senderName:senderName,senderId:senderId,isGroup:isGroup,read:(targetId===cid)};
    m.push(replyMsg);
    savemsgs(targetId,m);
    if(targetId===window.currentCid)renderMsgs(m);renderChatList();playSound('recv',targetId);
    return;
  }
  
  var textCards=availableCards.filter(function(c){return c.category!=='stickers'&&c.category!=='voices'&&c.category!=='emojis'&&c.category!=='kaomoji'&&c.category!=='image'});
  var emojiCards=availableCards.filter(function(c){return c.category==='emojis'});
  var kaomojiCards=availableCards.filter(function(c){return c.category==='kaomoji'});
  var stickerCards=availableCards.filter(function(c){return c.category==='stickers'});
  var voiceCards=availableCards.filter(function(c){return c.category==='voices'});
  var imageCards=availableCards.filter(function(c){return c.category==='image'});

  var reply='',pc=false,imgSrc='',voiceSrc='',voiceText='',isStickerImg=false;

  // 核心逻辑：仅有语音字卡 → 100%语音回复；仅有文字字卡 → 100%文字回复
  var onlyVoice=(textCards.length===0&&emojiCards.length===0&&kaomojiCards.length===0&&stickerCards.length===0&&imageCards.length===0&&voiceCards.length>0);
  var onlyText=(textCards.length>0&&emojiCards.length===0&&kaomojiCards.length===0&&stickerCards.length===0&&imageCards.length===0&&voiceCards.length===0);
  var onlyEmoji=(textCards.length===0&&emojiCards.length>0&&kaomojiCards.length===0&&stickerCards.length===0&&imageCards.length===0&&voiceCards.length===0);
  var onlyKaomoji=(textCards.length===0&&emojiCards.length===0&&kaomojiCards.length>0&&stickerCards.length===0&&imageCards.length===0&&voiceCards.length===0);
  var onlySticker=(textCards.length===0&&emojiCards.length===0&&kaomojiCards.length===0&&stickerCards.length>0&&imageCards.length===0&&voiceCards.length===0);
  var onlyImage=(textCards.length===0&&emojiCards.length===0&&kaomojiCards.length===0&&stickerCards.length===0&&imageCards.length>0&&voiceCards.length===0);
  
  if(onlyVoice){
    var vrc=voiceCards[Math.floor(Math.random()*voiceCards.length)];

    voiceSrc=vrc.content;
    voiceText=vrc.voiceText||'';
  }else if(onlySticker){
    var src=stickerCards[Math.floor(Math.random()*stickerCards.length)];

    imgSrc=src.content;
    isStickerImg=true;
  }else if(onlyImage){
    var imgRC=imageCards[Math.floor(Math.random()*imageCards.length)];
    imgSrc=imgRC.content;
    isStickerImg=false;
  }else if(onlyText){
    var pyEn=getSpeed('py-en',senderId),pyProb=getSpeed('py-prob',senderId)/100,pyMin=getSpeed('py-min',senderId),pyMax=getSpeed('py-max',senderId);
    if(pyEn&&Math.random()<pyProb){
      // ★ 修复：多条字卡同样优先用户自己的字卡，默认字卡按概率补充
      var userTextCardsAvl=textCards.filter(function(card){return card.content&&card.content.trim()&&card.type!=='default_common'});
      var dcTextCardsAvl=textCards.filter(function(card){return card.content&&card.content.trim()&&card.type==='default_common'});
      var avl=userTextCardsAvl.slice();
      // ★ 默认字卡已由 getDefaultCommonCardsForContact 按整体概率过滤（命中才返回），这里直接混入
      if(dcTextCardsAvl.length>0){
        avl=avl.concat(dcTextCardsAvl.slice(0,Math.max(1,Math.floor((userTextCardsAvl.length||1)*0.5))));
      }
      if(avl.length===0)avl=dcTextCardsAvl.slice();
      if(avl.length>=pyMin){
        var cnt=Math.max(pyMin,Math.floor(Math.random()*(Math.min(pyMax,avl.length)-pyMin+1))+pyMin);
        var selectedCards=avl.slice().sort(function(){return Math.random()-.5}).slice(0,cnt);
        reply=selectedCards.map(function(c){return c.content}).join(' ');
        
        pc=true;
      }
    }
    if(!reply&&textCards.length){
      // ★ 修复：优先用用户自己的字卡，默认通用字卡按概率"补充"而非按数量淹没
      // 避免默认字卡几百条数量占比导致几乎总是抽到默认字卡
      var userTextCards=textCards.filter(function(c){return c.type!=='default_common'});
      var dcTextCards=textCards.filter(function(c){return c.type==='default_common'});
      if(userTextCards.length>0){
        // ★ 默认字卡已由 getDefaultCommonCardsForContact 按整体概率过滤（命中才返回），这里直接混入
        if(dcTextCards.length>0){
          // 混合：从用户字卡和默认字卡里各按比例抽
          var pool=userTextCards.concat(dcTextCards.slice(0,Math.max(1,Math.floor(userTextCards.length*0.5))));
          var rc=pool[Math.floor(Math.random()*pool.length)];
          reply=rc.content;
        }else{
          var rc2=userTextCards[Math.floor(Math.random()*userTextCards.length)];
          reply=rc2.content;
        }
      }else{
        // 没有自己的字卡：直接用默认字卡
        var rc3=dcTextCards[Math.floor(Math.random()*dcTextCards.length)];
        reply=rc3.content;
      }
    }
  }else if(onlyEmoji){
    var erc=emojiCards[Math.floor(Math.random()*emojiCards.length)];
    
    reply=erc.content;
  }else if(onlyKaomoji){
    var krc=kaomojiCards[Math.floor(Math.random()*kaomojiCards.length)];
    
    reply=krc.content;
  }else{
    // 混合字卡：使用概率
    var stickerProb=getSpeed('sticker-prob',senderId);
    var isStickerReply=stickerCards.length>0&&Math.random()*100<stickerProb;

    var emojiProb=getSpeed('emoji-prob',senderId);
    var isEmojiReply=!isStickerReply&&emojiCards.length>0&&Math.random()*100<emojiProb;

    var imageProb=getSpeed('image-prob',senderId)||5;
    var isImageReply=!isStickerReply&&!isEmojiReply&&imageCards.length>0&&Math.random()*100<imageProb;

    var voiceProb=getSpeed('voice-prob',senderId)||10;
    if(textCards.length===0&&emojiCards.length===0&&voiceCards.length>0)voiceProb=100;
    var isVoiceReply=!isStickerReply&&!isEmojiReply&&!isImageReply&&voiceCards.length>0&&Math.random()*100<voiceProb;

    if(isStickerReply){
      var rc=stickerCards[Math.floor(Math.random()*stickerCards.length)];

      imgSrc=rc.content;
      isStickerImg=true;
    }else if(isImageReply){
      var irc=imageCards[Math.floor(Math.random()*imageCards.length)];
      imgSrc=irc.content;
      isStickerImg=false;
    }else if(isEmojiReply){
      var erc=emojiCards[Math.floor(Math.random()*emojiCards.length)];

      reply=erc.content;
    }else if(isVoiceReply){
      var vrc=voiceCards[Math.floor(Math.random()*voiceCards.length)];

      voiceSrc=vrc.content;
      voiceText=vrc.voiceText||'';
    }else{
      var pyEn=getSpeed('py-en',senderId),pyProb=getSpeed('py-prob',senderId)/100,pyMin=getSpeed('py-min',senderId),pyMax=getSpeed('py-max',senderId);
      if(pyEn&&Math.random()<pyProb){
        var avl=textCards.filter(function(card){return card.content&&card.content.trim()});
        if(avl.length>=pyMin){
          var cnt=Math.max(pyMin,Math.floor(Math.random()*(Math.min(pyMax,avl.length)-pyMin+1))+pyMin);
          var selectedCards=avl.slice().sort(function(){return Math.random()-.5}).slice(0,cnt);
          reply=selectedCards.map(function(c){return c.content}).join(' ');
          
          pc=true;
        }
      }
      if(!reply&&textCards.length){
        var rc=textCards[Math.floor(Math.random()*textCards.length)];
        
        reply=rc.content;
      }
      if(!reply&&!imgSrc&&!voiceSrc&&voiceCards.length>0){
        var vrc2=voiceCards[Math.floor(Math.random()*voiceCards.length)];
        
        voiceSrc=vrc2.content;
        voiceText=vrc2.voiceText||'';
        reply='';
      }
      if(!reply&&!imgSrc&&!voiceSrc)reply='请在字卡库里上传字卡后开始聊天';
      
      // 颜文字概率：独立于主字卡，可附加到文字回复中
      var kaomojiProb=getSpeed('kaomoji-prob',senderId);
      if(kaomojiProb>0&&kaomojiCards.length>0&&Math.random()*100<kaomojiProb){
        var kc=kaomojiCards[Math.floor(Math.random()*kaomojiCards.length)];
        
        if(reply&&reply!=='请在字卡库里上传字卡后开始聊天'){
          reply=reply+' '+kc.content;
        }else{
          reply=kc.content;
        }
      }
    }
  }
  
  var quoteMsgId=null;
  var quoteProb=getSpeed('quote-prob',senderId)/100;
  if(quoteProb>0&&Math.random()<quoteProb){
    var messages=msgs(targetId);
    var selfMsgs=messages.filter(function(m){return m.s===SELF});
    if(selfMsgs.length>0){
      quoteMsgId=selfMsgs[selfMsgs.length-1].id;
    }
  }
  
  var moodCard=await getRandomMoodCard(targetId);
  if(moodCard){emotionStreak+=1;}else{emotionStreak=0;}
  var heartCard=await getRandomHeartCard(targetId, moodCard);
  var intentCard=await getRandomIntentCard(targetId, heartCard);
  
  var m=msgs(targetId);
  if(!m||m.length===0){
    // ★ 修复：新联系人或空聊天记录时，创建新数组来发送第一条回复（而不是直接跳过）
    m=[];
  }
  var replyMsg={id:'m_'+Date.now()+'_'+Math.random().toString(36).substr(2,9),s:OTHER,t:reply,img:imgSrc,voice:voiceSrc,voiceText:voiceText,ts:new Date(),pc:pc,isAuto:true,isInitiative:false,quote:quoteMsgId,isSticker:isStickerImg,isVoice:voiceSrc?true:false,senderName:senderName,senderId:senderId,isGroup:isGroup,read:(targetId===cid),moodCard:moodCard,heartCard:heartCard,intentCard:intentCard};
  m.push(replyMsg);
  savemsgs(targetId,m);
  if(targetId===window.currentCid)renderMsgs(m);renderChatList();playSound('recv',targetId);
  
  setTimeout(function(){maybeTriggerStarMusicRequest(targetId)},2000);
  
  if(document.visibilityState !== 'visible'){
    var item=contacts.find(function(x){return x.id===targetId})||group;
    var msgText='';
    if(voiceSrc){msgText='[语音]';}
    else if(imgSrc){msgText='[图片]';}
    else if(reply){msgText=reply;}
    else{msgText='[表情]';}
    showPushNotification(item?item.name:'联系人',msgText,(item&&item.avatar)?item.avatar:'',targetId);
  }
  
  var rcProb=getSpeed('rc-prob',senderId);
  if(Math.random()*100<rcProb){
    setTimeout(function(){
      var all=msgs(targetId);
      if(all.length>0){
        var lastMsg=all[all.length-1];
        if(lastMsg.id===replyMsg.id){
          lastMsg.retracted=true;
          lastMsg.originalContent=lastMsg.t||'';
          lastMsg.originalImg=lastMsg.img||'';
          lastMsg.t='';
          lastMsg.img='';
          savemsgs(targetId,all);
          if(targetId===window.currentCid)renderMsgs(all);
          renderChatList();
        }
      }
    },(1+Math.random()*3)*1000);
  }
}
if($('msg-inp')){$('msg-inp').addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.shiftKey&&getSpeed('enter-send')===1){e.preventDefault();sendMsg()}});$('msg-inp').addEventListener('input',function(){this.style.height='auto';this.style.height=Math.min(this.scrollHeight,100)+'px';updateSendBtn()});}
