function resetTouchSettings(){ls('ml2_touch_cards_public',[]);ls('ml2_touch_cards_private',{});ls('ml2_touch_groups',{public:['默认'],private:['默认']});ls('ml2_touch_group_cards',{});toast('已重置')}
function importTouchCards(text){
  var lines=text.split('\n').map(function(l){return l.trim()}).filter(function(l){return l});
  if(lines.length===0){toast('请输入内容');return}
  
  if(currentCardType==='private'&&!selectedPrivateContact){toast('请先选择联系人');return}
  
  // 使用当前选中的分组作为默认分组
  var defaultGroup='默认';
  if(currentCardGroup&&currentCardGroup!=='all'&&currentCardGroup.indexOf('default_touch')===0){
    var dgParts=currentCardGroup.split('_');
    defaultGroup=dgParts[dgParts.length-1]||'默认';
  }else if(currentTouchGroup&&currentTouchGroup!=='all'){
    defaultGroup=currentTouchGroup;
  }
  var currentGroup=defaultGroup;
  var cardGroups={};
  
  lines.forEach(function(line){
    if(line.startsWith('【')&&line.endsWith('】')){
      currentGroup=line.substring(1,line.length-1);
      var groups=getTouchGroups(currentCardType);
      if(groups.indexOf(currentGroup)<0){
        groups.push(currentGroup);
        saveTouchGroups(currentCardType,groups);
      }
    }else{
      if(!cardGroups[currentGroup])cardGroups[currentGroup]=[];
      cardGroups[currentGroup].push(line);
    }
  });
  
  var totalAdded=0;
  for(var group in cardGroups){
    if(!cardGroups.hasOwnProperty(group))continue;
    var existingCards=getTouchCardsByGroup(currentCardType,group,selectedPrivateContact);
    var newCards=cardGroups[group];
    existingCards=existingCards.concat(newCards);
    saveTouchCardsByGroup(currentCardType,group,existingCards,selectedPrivateContact);
    totalAdded+=newCards.length;
  }
  
  if(totalAdded===0){toast('未检测到有效字卡内容');return}
  
  $('batch-touch-inp').value='';
  renderCardGroups();
  if(typeof _doRenderCardList==='function')_doRenderCardList();
  toast('已导入 '+totalAdded+' 条');
}
function deduplicateTouchCards(){
  var cards=getTouchCardsByGroup(currentCardType,currentTouchGroup,selectedPrivateContact);
  var unique=[];
  var seen={};
  cards.forEach(function(card){
    if(!seen[card]){
      seen[card]=true;
      unique.push(card);
    }
  });
  saveTouchCardsByGroup(currentCardType,currentTouchGroup,unique,selectedPrivateContact);
  renderCardGroups();
  if(typeof _doRenderCardList==='function')_doRenderCardList();
  toast('已移除重复，保留 '+unique.length+' 条');
}
function clearAllTouchCards(){
  var allGroups=getTouchGroups(currentCardType);
  allGroups.forEach(function(group){
    saveTouchCardsByGroup(currentCardType,group,[],selectedPrivateContact);
  });
  renderCardGroups();
  if(typeof _doRenderCardList==='function')_doRenderCardList();
  toast('已清空所有拍一拍字卡');
}

function showContactTouchMenu(contactId,avatarEl){renderTouchMenu(contactId)}
function showChatTouchMenu(contactId){renderTouchMenu(contactId)}
function readNavTouchCards(key){
  var result=[];
  try{
    var raw=safeGetItem(key);
    if(!raw){raw=ls(key);}
    if(raw){
      var arr=typeof raw==='string'?JSON.parse(raw):raw;
      if(Array.isArray(arr)){
        arr.forEach(function(c){
          if(c&&c.category==='touch'&&c.content){
            result.push({content:c.content,group:c.group||'默认',type:key.indexOf('public')>=0?'public':'private'});
          }
        });
      }
    }
  }catch(e){}
  try{
    var lfRaw=safeGetItem('ml2_lf_'+key);
    if(lfRaw){
      var lfArr=typeof lfRaw==='string'?JSON.parse(lfRaw):lfRaw;
      if(Array.isArray(lfArr)){
        lfArr.forEach(function(c){
          if(c&&c.category==='touch'&&c.content){
            var group=c.group||'默认';
            var exists=result.some(function(x){return x.content===c.content&&x.group===group});
            if(!exists)result.push({content:c.content,group:group,type:key.indexOf('public')>=0?'public':'private'});
          }
        });
      }
    }
  }catch(e){}
  return result;
}
function renderTouchMenu(contactId){
  var contact=contacts.find(function(c){return c.id===contactId});
  if(!contact)return;
  $('touch-contact-name').textContent='我对 '+contact.name;
  var list=$('touch-action-list');
  list.innerHTML='';
  var tabBox=$('touch-tabs-container');
  if(tabBox)tabBox.innerHTML='';

  var currentGroup='全部';
  var defaultActions=TOUCH_ACTIONS.slice();

  // ===== Old touch system: public cards + groups =====
  var pubCardsRaw=getAllTouchCards('public');
  var pubGroupOrder=getTouchGroups('public');
  var allOldPubCards=[];
  // 展开 old 系统每张卡的 {content, group}
  pubGroupOrder.forEach(function(gr){
    getTouchCardsByGroup('public',gr).forEach(function(text){
      if(text&&typeof text==='string')allOldPubCards.push({content:text,group:gr||'默认',type:'public'});
    });
  });
  // old system 中没有分组归属的 public 卡也塞进来
  getAllTouchCards('public').forEach(function(c){
    var content=typeof c==='string'?c:(c&&c.content);
    if(!content)return;
    var has=allOldPubCards.some(function(x){return x.content===content});
    if(!has)allOldPubCards.push({content:content,group:(typeof c==='object'&&c.group)||'默认',type:'public'});
  });

  // ===== Old touch system: private cards (current chat contact owns) =====
  var oldPrivateOwnedCards=[];
  var privGroupOrder=getTouchGroups('private');
  privGroupOrder.forEach(function(gr){
    getTouchCardsByGroup('private',gr,contactId).forEach(function(text){
      if(text&&typeof text==='string')oldPrivateOwnedCards.push({content:text,group:gr||'默认',type:'private'});
    });
  });
  getTouchCardsPrivate(contactId).forEach(function(c){
    var content=typeof c==='string'?c:(c&&c.content);
    if(!content)return;
    var has=oldPrivateOwnedCards.some(function(x){return x.content===content});
    if(!has)oldPrivateOwnedCards.push({content:content,group:(typeof c==='object'&&c.group)||'默认',type:'private'});
  });

  // ===== Nav system public touch cards =====
  var navPubCards=readNavTouchCards('ml2_nav_cards_public');
  navPubCards.forEach(function(c){
    var has=allOldPubCards.some(function(x){return x.content===c.content&&x.group===c.group});
    if(!has)allOldPubCards.push(c);
  });

  // ===== Nav system private cards (only cardPrivateContacts bound to contactId) =====
  var boundPrivateCards=[];
  (cardPrivateContacts||[]).forEach(function(pc){
    var isBound=pc.bindContactId===contactId;
    if(!isBound)return;
    // pc.id 是字卡联系人ID，nav 私钥是 ml2_nav_cards_private_{pc.id}
    var key='ml2_nav_cards_private_'+pc.id;
    readNavTouchCards(key).forEach(function(c){
      var has=boundPrivateCards.some(function(x){return x.content===c.content&&x.group===c.group});
      if(!has)boundPrivateCards.push(c);
    });
    // old system 私钥: private 类型 + 分组 + contactId === pc.id
    (getTouchGroups('private')).forEach(function(gr){
      getTouchCardsByGroup('private',gr,pc.id).forEach(function(text){
        if(!text||typeof text!=='string')return;
        var has=boundPrivateCards.some(function(x){return x.content===text&&x.group===gr});
        if(!has)boundPrivateCards.push({content:text,group:gr||'默认',type:'private'});
      });
    });
    getTouchCardsPrivate(pc.id).forEach(function(c){
      var content=typeof c==='string'?c:(c&&c.content);
      if(!content)return;
      var has=boundPrivateCards.some(function(x){return x.content===content});
      if(!has)boundPrivateCards.push({content:content,group:(typeof c==='object'&&c.group)||'默认',type:'private'});
    });
  });

  // 合并所有卡
  var allPubCards=allOldPubCards.filter(function(c){return c&&c.content});
  var allPrivCards=oldPrivateOwnedCards.concat(boundPrivateCards).filter(function(c,i,self){
    return c&&c.content&&self.findIndex(function(x){return x.content===c.content&&x.group===c.group})===i;
  });
  var allCards=allPubCards.concat(allPrivCards);

  // ===== Build group list =====
  var groups=['全部'];
  // 先加 public 卡中出现过的分组（按 group 名去重）
  function addGroupUnique(g){if(g&&groups.indexOf(g)<0)groups.push(g);}
  // 从 navCardGroups.public 读取公用字卡分组
  if(navCardGroups&&navCardGroups.public)navCardGroups.public.forEach(addGroupUnique);
  allPubCards.forEach(function(c){addGroupUnique(c.group);});
  // 再加 private 卡中出现过的分组（只在有绑定/私卡时显示，但公用字卡如果重名则不重复）
  if(allPrivCards.length>0){
    if(navCardGroups&&navCardGroups.private){
      Object.keys(navCardGroups.private).forEach(function(k){
        (navCardGroups.private[k]||[]).forEach(addGroupUnique);
      });
    }
    allPrivCards.forEach(function(c){addGroupUnique(c.group);});
  }

  // ===== Render tabs (only once, to dedicated container) =====
  var tabsHtml='<div id="touch-group-tabs" style="display:flex;flex-wrap:wrap;gap:4px;">';
  groups.forEach(function(g){
    tabsHtml+='<button class="touch-group-tab'+(g===currentGroup?' sel':'')+'" data-tg="'+g+'" style="padding:4px 10px;font-size:11px;border-radius:6px;border:1px solid var(--border);background:'+(g===currentGroup?'var(--accent)':'var(--c2)')+';color:'+(g===currentGroup?'#fff':'var(--txt)')+';cursor:pointer;">'+g+'</button>';
  });
  tabsHtml+='</div>';
  if(tabBox){tabBox.innerHTML=tabsHtml;}
  else{list.insertAdjacentHTML('beforebegin',tabsHtml);}

  function renderCards(group){
    list.innerHTML='';
    var cardsToShow=[];
    if(group==='全部'||group==='默认'){
      cardsToShow=cardsToShow.concat(defaultActions);
    }
    if(group==='全部'){
      allCards.forEach(function(c){if(c.content&&cardsToShow.indexOf(c.content)<0)cardsToShow.push(c.content);});
    }else{
      allCards.forEach(function(c){
        if(c.group===group&&c.content&&cardsToShow.indexOf(c.content)<0)cardsToShow.push(c.content);
      });
    }
    if(cardsToShow.length===0){
      list.innerHTML='<div style="text-align:center;color:var(--txt3);padding:20px;font-size:13px;">暂无拍一拍字卡</div>';
      return;
    }
    cardsToShow.forEach(function(action){
      if(!action)return;
      var btn=document.createElement('button');
      btn.className='btn';
      btn.style.width='100%';
      btn.style.justifyContent='flex-start';
      btn.textContent=action;
      btn.onclick=function(){performTouch(contactId,action);hideOv('ov-contact-touch');};
      list.appendChild(btn);
    });
  }
  renderCards(currentGroup);

  // Bind group tab clicks
  setTimeout(function(){
    var tabs=document.querySelectorAll('.touch-group-tab');
    tabs.forEach(function(tab){
      tab.addEventListener('click',function(){
        currentGroup=this.getAttribute('data-tg');
        tabs.forEach(function(t){
          t.classList.remove('sel');
          t.style.background='var(--c2)';
          t.style.color='var(--txt)';
        });
        this.classList.add('sel');
        this.style.background='var(--accent)';
        this.style.color='#fff';
        renderCards(currentGroup);
      });
    });
  },30);
  showOv('ov-contact-touch');
}
function showGroupTouchMemberSelect(groupId){
  var group = groups.find(function(g){return g.id===groupId});
  if(!group) return;
  var list = $('group-touch-member-list');
  if(!list) return;
  list.innerHTML = '';
  var memberIds = group.memberIds || [];
  if(!memberIds.length){ toast('群内暂无成员'); return; }
  memberIds.forEach(function(mid){
    var contact = contacts.find(function(c){return c.id===mid});
    if(!contact) return;
    var displayName = contact.name;
    if(group.memberSettings && group.memberSettings[mid] && group.memberSettings[mid].nickname){
      displayName = group.memberSettings[mid].nickname;
    }
    var row = document.createElement('button');
    row.className = 'btn';
    row.style.cssText = 'width:100%;justify-content:flex-start;padding:10px 14px;';
    row.textContent = displayName;
    row.onclick = function(){
      hideOv('ov-group-touch-select');
      showChatTouchMenu(mid);
    };
    list.appendChild(row);
  });
  showOv('ov-group-touch-select');
}
if($('touch-custom-send-btn'))$('touch-custom-send-btn').addEventListener('click',function(){var val=$('touch-custom-input').value.trim();if(!val){toast('请输入内容');return}var contactId=cid;performTouch(contactId,val);$('touch-custom-input').value='';hideOv('ov-contact-touch')});

// ============ Red Packet Functions (Redesigned) ============
var RP_CONFIG={
  systemTriggerRate:0.04,
  systemDailyLimit:5,
  specialPoolRate:0.4,
  specialAmounts:[5.2,52,520,5200,13.14,1314],
  randomSmallRate:0.8,
  randomSmallCap:200,
  returnRate:0.2,
  instantCollectRate:0.7,
  pendingCollectRate:0.08,
  expiryMs:24*3600*1000,
  triggerDelayMin:800,
  triggerDelayMax:2000,
  replyDelayMin:3000,
  replyDelayMax:8000,
  debugRate:null
};

// Wallet: {myBalance:number, systemBalance:number} in cents (1 yuan = 100 cents)
function getWallet(contactId){
  var w=ls('ml2_rp_wallet_'+contactId);
  if(!w||typeof w!=='object'){w={myBalance:100000,systemBalance:100000};ls('ml2_rp_wallet_'+contactId,w);}
  if(typeof w.myBalance!=='number')w.myBalance=100000;
  if(typeof w.systemBalance!=='number')w.systemBalance=100000;
  return w;
}
function saveWallet(contactId,w){ls('ml2_rp_wallet_'+contactId,w);}

// Packet records
function getPackets(contactId){return ls('ml2_rp_packets_'+contactId)||[];}
function savePackets(contactId,packets){ls('ml2_rp_packets_'+contactId,packets);}
function getPacketById(contactId,rpId){
  var packets=getPackets(contactId);
  return packets.find(function(p){return p.id===rpId});
}
function updatePacketRecord(contactId,updatedRp){
  var packets=getPackets(contactId);
  for(var i=0;i<packets.length;i++){
    if(packets[i].id===updatedRp.id){packets[i]=updatedRp;break;}
  }
  savePackets(contactId,packets);
}

// Daily counter
function getDailyCounter(contactId){
  var today=new Date().toISOString().slice(0,10);
  var counter=ls('ml2_rp_daily_'+contactId);
  if(!counter||counter.date!==today){counter={date:today,count:0};ls('ml2_rp_daily_'+contactId,counter);}
  return counter;
}
function incrementDailyCounter(contactId){
  var counter=getDailyCounter(contactId);
  counter.count++;
  ls('ml2_rp_daily_'+contactId,counter);
}

// Create packet record
function createPacket(contactId,direction,amountCents,message){
  var rp={
    id:'rp_'+Date.now()+'_'+Math.random().toString(36).substr(2,9),
    contactId:contactId,
    direction:direction,
    amount:amountCents,
    status:'pending',
    message:message||'',
    createdAt:Date.now(),
    processedAt:null
  };
  var packets=getPackets(contactId);
  packets.push(rp);
  savePackets(contactId,packets);
  return rp;
}

// Render red packet as a chat message
function renderRedPacketCard(contactId,rp){
  var m=msgs(contactId);
  var amountYuan=(rp.amount/100).toFixed(2);
  var isMySend=rp.direction==='send';
  var contact=contacts.find(function(c){return c.id===contactId});
  m.push({
    id:'m_'+rp.id,
    s:isMySend?SELF:OTHER,
    t:'',
    ts:new Date(rp.createdAt),
    pc:false,
    isRedpacket:true,
    redpacketAmount:amountYuan,
    redpacketGreeting:rp.message||'恭喜发财，大吉大利',
    redpacketStatus:rp.status,
    redpacketDirection:rp.direction,
    redpacketRpId:rp.id,
    redpacketOpened:rp.status==='received',
    read:isMySend?true:false,
    senderName:isMySend?'我':(contact?contact.name:'TA'),
    senderId:isMySend?me.id:contactId
  });
  savemsgs(contactId,m);
  if(cid===contactId)renderMsgs(m);
  renderChatList();
  try{renderContactRedPacketHistory(contactId)}catch(e){}
  if(!isMySend){
    var uids=ls('ml2_uids')||{};
    if(!uids[contactId])uids[contactId]=0;
    uids[contactId]++;
    ls('ml2_uids',uids);
  }
}

// Update message status in chat
function updateRedPacketMessageStatus(contactId,rpId,newStatus){
  var m=msgs(contactId);
  var updated=false;
  for(var i=0;i<m.length;i++){
    if(m[i].redpacketRpId===rpId){
      m[i].redpacketStatus=newStatus;
      m[i].redpacketOpened=(newStatus==='received');
      updated=true;
      break;
    }
  }
  if(updated){
    savemsgs(contactId,m);
    if(cid===contactId)renderMsgs(m);
    renderChatList();
    try{renderContactRedPacketHistory(contactId)}catch(e){}
  }
  return updated;
}

function pushCollectedCard(contactId,rp,isSelfCollect){
  var m=msgs(contactId);
  var amountYuan=(rp.amount/100).toFixed(2);
  var contact=contacts.find(function(c){return c.id===contactId});
  var collectorName=isSelfCollect?'我':(contact?contact.name:'TA');
  var senderName=isSelfCollect?(contact?contact.name:'TA'):'我';
  var collectedMsg=isSelfCollect?'我领取了'+(contact?contact.name:'TA')+'的红包':(contact?contact.name:'TA')+'领取了你的红包';
  m.push({
    id:'m_collected_'+rp.id,
    s:isSelfCollect?SELF:OTHER,
    t:'',
    ts:new Date(),
    pc:false,
    isRedpacketCollected:true,
    redpacketCollectedAmount:amountYuan,
    redpacketCollectedText:collectedMsg,
    read:true,
    senderName:isSelfCollect?'我':(contact?contact.name:'TA'),
    senderId:isSelfCollect?me.id:contactId
  });
  savemsgs(contactId,m);
  if(cid===contactId)renderMsgs(m);
  renderChatList();
}

function showNotification(title,body){
  toast(title);
  if('Notification' in window&&Notification.permission==='granted'){
    try{var n=new Notification(title,{body:body,icon:'',tag:'redpacket-'+Date.now()});setTimeout(function(){n.close()},4000)}catch(e){}
  }
}

// Red packet greeting pool (20 items with weighted probability)
var RP_GREETING_POOL=[
  // 宠溺 (4 items, weight 2 = 8 total)
  {text:'拿去买奶茶',weight:2,category:'宠溺'},
  {text:'今天零花钱',weight:2,category:'宠溺'},
  {text:'随便花',weight:2,category:'宠溺'},
  {text:'买点好吃的',weight:2,category:'宠溺'},
  // 温柔 (4 items, weight 2 = 8 total)
  {text:'收下嘛',weight:2,category:'温柔'},
  {text:'手滑了一下',weight:2,category:'温柔'},
  {text:'不许拒绝',weight:2,category:'温柔'},
  {text:'偷偷塞给你的',weight:2,category:'温柔'},
  // 调皮 (4 items, weight 1 = 4 total)
  {text:'捡到钱了分你一半',weight:1,category:'调皮'},
  {text:'今天心情好~',weight:1,category:'调皮'},
  {text:'嘘，别告诉别人',weight:1,category:'调皮'},
  {text:'发工资了',weight:1,category:'调皮'},
  // 日常 (4 items, weight 1 = 4 total)
  {text:'今天的咖啡我请',weight:1,category:'日常'},
  {text:'路上看到就想到你了',weight:1,category:'日常'},
  {text:'补上昨天的',weight:1,category:'日常'},
  {text:'刚好有零钱',weight:1,category:'日常'},
  // 惊喜 (4 items, weight 1 = 4 total)
  {text:'没有理由就是想发',weight:1,category:'惊喜'},
  {text:'突然想你了',weight:1,category:'惊喜'},
  {text:'打开有惊喜',weight:1,category:'惊喜'},
  {text:'奖励你的',weight:1,category:'惊喜'}
];

function getRandomRedPacketGreeting(){
  var totalWeight=0;
  for(var i=0;i<RP_GREETING_POOL.length;i++){totalWeight+=RP_GREETING_POOL[i].weight;}
  var r=Math.random()*totalWeight;
  var cumulative=0;
  for(var j=0;j<RP_GREETING_POOL.length;j++){
    cumulative+=RP_GREETING_POOL[j].weight;
    if(r<cumulative)return RP_GREETING_POOL[j].text;
  }
  return RP_GREETING_POOL[0].text;
}

// System auto-send (TA → me), 4% trigger
function trySystemAutoSend(contactId){
  if(!contactId)return;
  var counter=getDailyCounter(contactId);
  if(counter.count>=RP_CONFIG.systemDailyLimit)return;
  var triggerRate=(RP_CONFIG.debugRate!==null&&RP_CONFIG.debugRate!==undefined)?RP_CONFIG.debugRate:RP_CONFIG.systemTriggerRate;
  if(Math.random()>=triggerRate)return;
  var wallet=getWallet(contactId);
  if(wallet.systemBalance<1)return;
  incrementDailyCounter(contactId);
  var amountCents;
  if(Math.random()<RP_CONFIG.specialPoolRate){
    var pool=RP_CONFIG.specialAmounts;
    amountCents=Math.round(pool[Math.floor(Math.random()*pool.length)]*100);
  }else{
    if(Math.random()<RP_CONFIG.randomSmallRate){
      var cap=Math.min(RP_CONFIG.randomSmallCap*100,wallet.systemBalance);
      amountCents=Math.floor(Math.random()*cap)+1;
    }else{
      amountCents=Math.floor(Math.random()*wallet.systemBalance)+1;
    }
  }
  if(amountCents>wallet.systemBalance)amountCents=wallet.systemBalance;
  wallet.systemBalance-=amountCents;
  saveWallet(contactId,wallet);
  var msg=getRandomRedPacketGreeting();
  var rp=createPacket(contactId,'receive',amountCents,msg);
  renderRedPacketCard(contactId,rp);
}

// User manual send
function sendRedPacket(contactId,amountYuan,message){
  if(!contactId)return false;
  var amountCents=Math.round(Number(amountYuan)*100);
  if(isNaN(amountCents)||amountCents<1){toast('请输入有效金额');return false;}
  var wallet=getWallet(contactId);
  if(amountCents>wallet.myBalance){toast('余额不足');return false;}
  wallet.myBalance-=amountCents;
  saveWallet(contactId,wallet);
  var rp=createPacket(contactId,'send',amountCents,message||'恭喜发财，大吉大利');
  renderRedPacketCard(contactId,rp);
  hideOv('ov-redpacket');
  toast('红包已发送');
  var delay=RP_CONFIG.replyDelayMin+Math.random()*(RP_CONFIG.replyDelayMax-RP_CONFIG.replyDelayMin);
  setTimeout(function(){handleSendResponse(contactId,rp);},delay);
  return true;
}

// System response to user's red packet (return / instant collect / pending)
function handleSendResponse(contactId,rp){
  if(!contactId||!rp){console.warn('handleSendResponse: invalid params');return;}
  var r=Math.random();
  if(r<RP_CONFIG.returnRate){
    rp.status='returned';rp.processedAt=Date.now();
    var w=getWallet(contactId);w.myBalance+=rp.amount;saveWallet(contactId,w);
    updatePacketRecord(contactId,rp);
    updateRedPacketMessageStatus(contactId,rp.id,'returned');
    return;
  }
  var collectThreshold=RP_CONFIG.instantCollectRate/(1-RP_CONFIG.returnRate);
  if(r<RP_CONFIG.returnRate+collectThreshold*(1-RP_CONFIG.returnRate)){
    rp.status='received';rp.processedAt=Date.now();
    var w2=getWallet(contactId);w2.systemBalance+=rp.amount;saveWallet(contactId,w2);
    updatePacketRecord(contactId,rp);
    updateRedPacketMessageStatus(contactId,rp.id,'received');
    pushCollectedCard(contactId,rp,false);
    playSound('recvSound',contactId);
    showNotification('红包已被领取','TA 领取了你的 ¥'+(rp.amount/100).toFixed(2)+' 红包');
  }else{
    rp.status='pending';
    updatePacketRecord(contactId,rp);
    updateRedPacketMessageStatus(contactId,rp.id,'pending');
  }
}

// Try collect pending packets (I sent, waiting for TA)
function tryCollectPending(contactId){
  if(!contactId)return;
  var packets=getPackets(contactId);
  var pending=packets.filter(function(p){return p.direction==='send'&&p.status==='pending';});
  if(pending.length===0)return;
  if(Math.random()<RP_CONFIG.pendingCollectRate){
    var rp=pending[0];
    rp.status='received';rp.processedAt=Date.now();
    var w=getWallet(contactId);w.systemBalance+=rp.amount;saveWallet(contactId,w);
    updatePacketRecord(contactId,rp);
    updateRedPacketMessageStatus(contactId,rp.id,'received');
    pushCollectedCard(contactId,rp,false);
    playSound('recvSound',contactId);
    showNotification('红包已被领取','TA 领取了你的 ¥'+(rp.amount/100).toFixed(2)+' 红包');
  }
}

// Check expiry
function checkExpiry(contactId){
  if(!contactId)return;
  var now=Date.now();
  var packets=getPackets(contactId);
  var changed=false;
  packets.forEach(function(rp){
    if(rp.status==='pending'&&now-rp.createdAt>RP_CONFIG.expiryMs){
      rp.status='expired';rp.processedAt=now;
      var w=getWallet(contactId);
      if(rp.direction==='send')w.myBalance+=rp.amount;
      else w.systemBalance+=rp.amount;
      saveWallet(contactId,w);
      updateRedPacketMessageStatus(contactId,rp.id,'expired');
      changed=true;
    }
  });
  if(changed)savePackets(contactId,packets);
}

// Called after each reply finishes
function onReplyFinished(contactId){
  if(!contactId)return;
  setTimeout(function(){trySystemAutoSend(contactId);},RP_CONFIG.triggerDelayMin+Math.random()*(RP_CONFIG.triggerDelayMax-RP_CONFIG.triggerDelayMin));
  setTimeout(function(){tryCollectPending(contactId);},1200+Math.random()*1500);
  setTimeout(function(){checkExpiry(contactId);},500);
  // 礼物：和红包一样，回复后按概率随机触发
  // 防御：GIFT_CONFIG 可能在文件加载完成前的早期回复中尚未赋值（var 提升但赋值在后部）
  if(window.GIFT_CONFIG&&GIFT_CONFIG.triggerDelayMin!==undefined){
    setTimeout(function(){trySystemAutoGift(contactId);},GIFT_CONFIG.triggerDelayMin+Math.random()*(GIFT_CONFIG.triggerDelayMax-GIFT_CONFIG.triggerDelayMin));
  }
}

// User clicks to open a red packet (TA sent to me)
function openRedPacketMessage(contactId,rpId){
  var rp=getPacketById(contactId,rpId);
  if(!rp){
    toast('红包记录不存在');
    return;
  }
  // If already collected, just show the opened modal
  if(rp.status==='received'||rp.status==='returned'||rp.status==='expired'){
    var contact2=contacts.find(function(c){return c.id===contactId});
    var amountYuan2=(rp.amount/100).toFixed(2);
    $('opened-redpacket-from').textContent='来自 '+((contact2?contact2.name:'TA'));
    $('opened-redpacket-amount').textContent=amountYuan2;
    $('opened-redpacket-greeting').textContent=rp.message||'';
    $('opened-redpacket-status').textContent=rp.status==='received'?'红包已存入你的余额':(rp.status==='returned'?'红包已退回':'红包已过期');
    showOv('ov-redpacket-opened');
    return;
  }
  if(rp.status!=='pending')return;
  rp.status='received';rp.processedAt=Date.now();
  var w=getWallet(contactId);w.myBalance+=rp.amount;saveWallet(contactId,w);
  updatePacketRecord(contactId,rp);
  updateRedPacketMessageStatus(contactId,rpId,'received');
  pushCollectedCard(contactId,rp,true);
  var contact=contacts.find(function(c){return c.id===contactId});
  var amountYuan=(rp.amount/100).toFixed(2);
  $('opened-redpacket-from').textContent='来自 '+((contact?contact.name:'TA'));
  $('opened-redpacket-amount').textContent=amountYuan;
  $('opened-redpacket-greeting').textContent=rp.message||'';
  $('opened-redpacket-status').textContent='红包已存入你的余额';
  showOv('ov-redpacket-opened');
}

// Handle red packet click
function handleRedPacketClick(msgId,sender,event){
  if(event&&event.stopPropagation)event.stopPropagation();
  var m=msgs(cid);
  for(var i=0;i<m.length;i++){
    if(m[i].id===msgId && (m[i].isRedpacket||m[i].redpacketRpId)){
      var status=m[i].redpacketStatus||(m[i].redpacketOpened?'received':'pending');
      if(status==='received'){
        if(sender===SELF){toast('TA 已领取你的红包');}else{toast('红包已领取');}
        break;
      }
      if(status==='returned'){toast('红包已退回');break;}
      if(status==='expired'){toast('红包已过期');break;}
      if(status==='pending'){
        if(sender===SELF){toast('等待TA领取...');break;}
        var rpId=m[i].redpacketRpId||m[i].id.replace('m_','');
        openRedPacketMessage(cid,rpId);
        break;
      }
      break;
    }
  }
}

