        htmlParts.push('<div class="message-call-row"><div class="message-call" style="cursor:default;">✏️ '+_hlText_LS.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')+'</div></div>');
        lt=d.getTime();
