var CURRENT_VERSION = '1.6';

function compareVersions(v1, v2) {
  var parts1 = v1.split('.').map(Number);
  var parts2 = v2.split('.').map(Number);
  var len = Math.max(parts1.length, parts2.length);
  for (var i = 0; i < len; i++) {
    var p1 = parts1[i] || 0;
    var p2 = parts2[i] || 0;
    if (p1 > p2) return 1;
    if (p1 < p2) return -1;
  }
  return 0;
}

function getLastReadVersion() {
  try {
    return localStorage.getItem('star_last_read_version') || '0.0';
  } catch(e) {
    return '0.0';
  }
}

function setLastReadVersion(version) {
  try {
    localStorage.setItem('star_last_read_version', version);
  } catch(e) {}
}

function showUpdateNotice(notice) {
  var overlay = document.getElementById('update-notice-overlay');
  if (!overlay) return;
  
  document.getElementById('update-notice-title').innerHTML = '✨ ' + notice.title;
  document.getElementById('update-notice-version').textContent = '版本 ' + notice.version;
  document.getElementById('update-notice-date').textContent = notice.date;
  document.getElementById('update-notice-body').innerHTML = notice.content;
  
  overlay.classList.add('show');
}

function closeUpdateNotice() {
  var overlay = document.getElementById('update-notice-overlay');
  if (overlay) {
    overlay.classList.remove('show');
  }
  setLastReadVersion(CURRENT_VERSION);
}

function checkUpdateNotice() {
  var lastRead = getLastReadVersion();
  var latestNotice = UPDATE_NOTICES[0];
  
  if (!latestNotice) return;
  
  if (compareVersions(latestNotice.version, lastRead) > 0) {
    showUpdateNotice(latestNotice);
  }
}

function renderUpdateHistory() {
  var list = document.getElementById('update-history-list');
  if (!list) return;
  
  var html = '';
  UPDATE_NOTICES.forEach(function(notice, index) {
    html += '<div class="update-history-item' + (index === 0 ? ' expanded' : '') + '" data-version="' + notice.version + '">' +
      '<div class="update-history-header" onclick="toggleUpdateHistory(this)">' +
        '<div class="update-history-info">' +
          '<div class="update-history-title">✨ ' + notice.title + '<span class="update-history-version">' + notice.version + '</span></div>' +
          '<div class="update-history-date">' + notice.date + '</div>' +
          '<div class="update-history-summary">' + notice.summary + '</div>' +
        '</div>' +
        '<div class="update-history-arrow">▼</div>' +
      '</div>' +
      '<div class="update-history-content">' +
        '<div class="update-history-content-inner">' + notice.content + '</div>' +
      '</div>' +
    '</div>';
  });
  
  list.innerHTML = html;
}

function toggleUpdateHistory(header) {
  var item = header.parentElement;
  item.classList.toggle('expanded');
}

function bindUpdateNoticeEvents() {
  var btn = document.getElementById('update-history-btn');
  if (btn) {
    btn.addEventListener('click', function() {
      showPg('pg-update-history');
    });
  }
  
  var usageBtn = document.getElementById('usage-notice-btn');
  if (usageBtn) {
    usageBtn.addEventListener('click', function() {
      showPg('pg-usage-notice');
    });
  }
  
  var overlay = document.getElementById('update-notice-overlay');
  if (overlay) {
    overlay.addEventListener('click', function(e) {
      if (e.target === overlay) {
        closeUpdateNotice();
      }
    });
  }
  
  showPgCallbacks['pg-update-history'] = function() {
    renderUpdateHistory();
  };
  
}

function initUpdateNotice() {
  bindUpdateNoticeEvents();
  // 取消公告弹窗：不再自动弹出更新公告，用户可通过「设置 → 更新公告」主动查看
}

// 从开屏点击"使用须知"按钮：关闭开屏并进入使用须知页面
function showUsageNoticeFromSplash() {
  // #region debug-point B:splash-function
  console.log('[DEBUG] showUsageNoticeFromSplash called');
  // #endregion
  try{
    var ann = document.getElementById('announcement-screen');
    if (ann) {
      // #region debug-point B1:hide-announcement
      console.log('[DEBUG] hiding announcement screen');
      // #endregion
      ann.style.opacity = '0';
      ann.style.pointerEvents = 'none';
      setTimeout(function() {
        ann.style.display = 'none';
      }, 500);
    }
    var phone = document.querySelector('.phone');
    if (phone) {
      // #region debug-point B2:show-phone
      console.log('[DEBUG] showing phone');
      // #endregion
      phone.style.display = 'flex';
      phone.style.opacity = '1';
    }
    // 修复：先切换到使用须知页面，再显示 phone，避免用户看到短暂的聊天列表
    try{
      // #region debug-point B3:show-pg
      console.log('[DEBUG] showing pg-usage-notice');
      // #endregion
      showPg('pg-usage-notice');
      // #region debug-point B4:render-chatlist
      console.log('[DEBUG] rendering chat list');
      // #endregion
      renderChatList();
      // 首次强制模式：隐藏顶部返回栏和底部导航栏，显示开始按钮
      var seen = getNoticeSeen();
      // #region debug-point B5:check-notice-seen
      console.log('[DEBUG] getNoticeSeen:', seen);
      // #endregion
      if (!seen) {
        var nav = document.getElementById('usage-notice-nav');
        if (nav) nav.style.display = 'none';
        var tabs = document.getElementById('usage-notice-tabs');
        if (tabs) tabs.style.display = 'none';
        var startBtn = document.getElementById('usage-notice-start-btn');
        if (startBtn) startBtn.style.display = 'block';
      } else {
        // 非首次：确保导航栏和标签栏正常显示，隐藏强制按钮
        var startBtn = document.getElementById('usage-notice-start-btn');
        if (startBtn) startBtn.style.display = 'none';
      }
    }catch(e){
      console.error('showUsageNoticeFromSplash inner error:',e);
    }
  }catch(e){
    console.error('showUsageNoticeFromSplash error:',e);
    var phone = document.querySelector('.phone');
    if(phone){phone.style.display='flex';phone.style.opacity='1';}
    var ann = document.getElementById('announcement-screen');
    if(ann){ann.style.display='none';ann.style.pointerEvents='none';}
    try{showPg('pg-list');renderChatList();}catch(e2){}
  }
}

window.showUpdateNoticeManual = function() {
  var latestNotice = UPDATE_NOTICES[0];
  if (latestNotice) {
    showUpdateNotice(latestNotice);
  }
};

window.resetUpdateNoticeRead = function() {
  setLastReadVersion('0.0');
  toast('已重置阅读记录，刷新页面后将重新显示公告');
};

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initUpdateNotice);
} else {
  initUpdateNotice();
}


// ========== 首次访问强制使用须知 ==========
var NOTICE_SEEN_KEY = 'star_usage_notice_seen';
var NOTICE_SEEN_COOKIE = 'star_notice_seen';

function saveNoticeSeen() {
  window._noticeSeen = true;
  try { sessionStorage.setItem(NOTICE_SEEN_KEY, '1'); } catch(e) {}
  try { localStorage.setItem(NOTICE_SEEN_KEY, '1'); } catch(e) {}
  try { document.cookie = NOTICE_SEEN_COOKIE + '=1;path=/;max-age=31536000'; } catch(e) {}
  if(window.localforage){
    try { window.localforage.setItem(NOTICE_SEEN_KEY, '1'); } catch(e) {}
  }
}

function getNoticeSeen() {
  if(window._noticeSeen) return '1';
  try {
    var v = sessionStorage.getItem(NOTICE_SEEN_KEY);
    if(v) return v;
  } catch(e) {}
  try {
    var v = localStorage.getItem(NOTICE_SEEN_KEY);
    if(v) return v;
  } catch(e) {}
  try {
    var cookies = document.cookie ? document.cookie.split(';') : [];
    for(var i = 0; i < cookies.length; i++){
      var c = cookies[i].trim();
      if(c.indexOf(NOTICE_SEEN_COOKIE + '=') === 0) return '1';
    }
  } catch(e) {}
  return null;
}

function finishFirstTimeNotice() {
  try{
    saveNoticeSeen();
    hasEnteredApp=true;
    // 恢复顶部栏和底部导航栏
    var nav = document.getElementById('usage-notice-nav');
    if (nav) nav.style.display = '';
    var tabs = document.getElementById('usage-notice-tabs');
    if (tabs) tabs.style.display = '';
    var phone = document.querySelector('.phone');
    if (phone) {
      phone.style.display = 'flex';
      phone.style.opacity = '1';
    }
    
    // 首次使用须知完成后，进入主界面
    
    // 如果初始化已完成，直接渲染
    if(appInitDone){
      setTimeout(function(){
        try{showPg('pg-list');renderChatList();}catch(e){console.error('finishFirstTimeNotice render error:',e);}
      }, 100);
      return;
    }
    
    // 初始化未完成，显示加载状态并等待
    showPg('pg-list');
    var clistInner = document.getElementById('clist-inner');
    if(clistInner) clistInner.innerHTML = '<div class="empty" style="padding:60px 0"><div style="font-size:40px;margin-bottom:16px;animation:splashPulse 1.5s ease-in-out infinite">✦</div><div style="font-size:14px;color:var(--txt3)">正在加载...</div></div>';
    
    var checkInterval = setInterval(function(){
      if(appInitDone){
        clearInterval(checkInterval);
        try{renderChatList();}catch(e){}
      }
    },200);
    
    setTimeout(function(){
      clearInterval(checkInterval);
      if(!appInitDone) try{renderChatList();}catch(e){}
    },10000);
  }catch(e){
    console.error('finishFirstTimeNotice error:',e);
    var phone=document.querySelector('.phone');
    if(phone){phone.style.display='flex';phone.style.opacity='1';}
    try{showPg('pg-list');renderChatList();}catch(e2){}
  }
}

(function initFirstTimeCheck() {
  try {
    var seen = getNoticeSeen();
    
    if (seen) {
      // 已看过使用须知：改为两个按钮（使用须知 + 进入）
      var splashBtns = document.getElementById('splash-buttons');
      if (splashBtns) {
        splashBtns.innerHTML = '<button id="splash-usage-btn" onclick="showUsageNoticeFromSplash()" style="flex:1;padding:14px;border:1.5px solid #d4c9b8;border-radius:12px;background:rgba(255,255,255,0.7);color:#8c7b6b;font-size:14px;font-weight:500;cursor:pointer;letter-spacing:2px;min-height:48px;touch-action:manipulation;-webkit-tap-highlight-color:transparent;transition:all 0.2s;">使用须知</button>' +
          '<button id="splash-enter-btn" onclick="enterApp()" style="flex:1;padding:14px;border:none;border-radius:12px;background:linear-gradient(135deg, #3d3429 0%, #2c2416 100%);color:#fff;font-size:14px;font-weight:500;cursor:pointer;letter-spacing:2px;min-height:48px;touch-action:manipulation;-webkit-tap-highlight-color:transparent;box-shadow:0 2px 8px rgba(44,36,22,0.15);transition:all 0.2s;">进入</button>';
        
        // 为移动端兼容添加 touchend 事件
        var enterBtn = document.getElementById('splash-enter-btn');
        if (enterBtn) {
          enterBtn.addEventListener('touchend', function(e) {
            e.preventDefault();
            e.stopPropagation();
            enterApp();
          });
        }
        var usageBtn = document.getElementById('splash-usage-btn');
        if (usageBtn) {
          usageBtn.addEventListener('touchend', function(e) {
            e.preventDefault();
            e.stopPropagation();
            showUsageNoticeFromSplash();
          });
        }
      }
    }
  } catch(e) {
    console.error('initFirstTimeCheck error:', e);
  }
})();
